    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, v_level_id, 'Membiasakan Diri (～ようにする)', 'Pelajari cara menyatakan usaha sadar dan rutinitas sehat atau target belajar dengan pola ～ようにする dalam keseharian di Jepang.', 'curriculum', 1);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, '786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, 'Kosakata Kebiasaan Sehat & Target Belajar', 'Kosakata Rutinitas', 'n3-u1-kosakata', 'cards', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('93cec210-4db4-5269-a4c2-dd3111d425b3'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang menjaga kebugaran: 毎日30分 ___ を続けています。', '{"options": ["運動", "運転", "通勤", "出張"], "translation": "Saya terus melakukan olahraga selama 30 menit setiap hari.", "sentence_template": "毎日30分 [blank] を続けています。"}'::jsonb, '{"selected": "運動"}'::jsonb, '運動 (undou) berarti olahraga. 運転 berarti menyetir, 通勤 berarti pergi bekerja, dan 出張 berarti dinas luar kota.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3f0411f7-8c13-547c-8d4b-aabb2bfe77af'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk rutinitas makan: 栄養の ___ を考えて食事を作ります。', '{"options": ["バランス", "スケジュール", "キャンセル", "アドバイス"], "translation": "Saya memasak makanan dengan memikirkan keseimbangan gizi.", "sentence_template": "栄養の [blank] を考えて食事を作ります。"}'::jsonb, '{"selected": "バランス"}'::jsonb, '栄養のバランス (eiyou no baransu) adalah kolokasi umum yang berarti keseimbangan gizi.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c47c997b-dcb6-5591-bff8-97975561a0e9'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kebiasaan belajar: 寝る前にその日の授業を ___ します。', '{"options": ["復習", "欠席", "遅刻", "提出"], "translation": "Sebelum tidur, saya mengulang pelajaran hari itu.", "sentence_template": "寝る前にその日の授業を [blank] します。"}'::jsonb, '{"selected": "復習"}'::jsonb, '復習 (fukushuu) berarti mengulang pelajaran. 欠席 (absen), 遅刻 (terlambat), dan 提出 (mengumpulkan tugas) tidak sesuai konteks.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3b9de5aa-dd09-5881-aeff-fe853f1ed2a0'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 毎朝同じ時間に起きる ___ がつきました。', '{"options": ["習慣", "予定", "予約", "経験"], "translation": "Saya sudah terbentuk kebiasaan bangun pada jam yang sama setiap pagi.", "sentence_template": "毎朝同じ時間に起きる [blank] がつきました。"}'::jsonb, '{"selected": "習慣"}'::jsonb, '習慣がつく (shuukan ga tsuku) berarti terbentuk suatu kebiasaan.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('73c9efe0-d598-5323-a2aa-55d8bc10a624'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'listening', 'listening_choice', 'Apa target belajar yang sedang dijalani pembicara setiap hari?', '{"audio_text": "試験に合格するために、毎日新しい漢字を十個覚える目標を立てました。", "options": [{"id": "opt_1", "text": "Menghafal sepuluh kanji baru setiap hari"}, {"id": "opt_2", "text": "Membaca sepuluh halaman novel setiap malam"}, {"id": "opt_3", "text": "Menulis sepuluh email kerja dalam bahasa Jepang"}, {"id": "opt_4", "text": "Menghafal sepuluh pola tata bahasa setiap minggu"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'Pembicara mengatakan 毎日新しい漢字を十個覚える目標を立てました (membuat target menghafal 10 kanji baru setiap hari).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1e638b6d-018a-555b-a8e0-f0a6cf96e3c9'::uuid, '740c7717-808f-5cd0-a75f-dfda8ffc150f'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara mulai mengurangi minuman manis?', '{"audio_text": "健康診断の結果を見て、甘い飲み物を控えて水を多く飲むことにしました。", "options": [{"id": "opt_1", "text": "Karena harga minuman manis di toko naik"}, {"id": "opt_2", "text": "Karena melihat hasil pemeriksaan kesehatan"}, {"id": "opt_3", "text": "Karena dokter melarang minum air dingin"}, {"id": "opt_4", "text": "Karena ingin menghemat biaya makan siang"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '健康診断の結果を見て berarti ''setelah melihat hasil pemeriksaan kesehatan''.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, '786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, 'Pola ～ようにする & ～ようにしている', 'Pola You ni Suru', 'n3-u1-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('37fa9aad-6064-5a7f-89e7-ea81f97b3545'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi pola membiasakan diri: 毎日野菜をたくさん ___ しています。', '{"options": ["食べるように", "食べたように", "食べてように", "食べますように"], "translation": "Saya membiasakan diri makan banyak sayur setiap hari.", "sentence_template": "毎日野菜をたくさん [blank] しています。"}'::jsonb, '{"selected": "食べるように"}'::jsonb, 'Pola ～ようにする memakai bentuk kamus (食べる) atau bentuk-NAI sebelum ようにする.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6f179ffa-8c9d-5069-8360-1cd6f994a984'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk negatif yang benar: 会議に ___ 気をつけています。', '{"options": ["遅れないように", "遅れるように", "遅れなかったように", "遅れませんように"], "translation": "Saya berhati-hati agar tidak terlambat rapat.", "sentence_template": "会議に [blank] 気をつけています。"}'::jsonb, '{"selected": "遅れないように"}'::jsonb, 'Untuk menyatakan usaha agar tidak melakukan sesuatu, gunakan Bentuk-NAI + ように (遅れないように).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0e59dfdc-e00e-5e19-9142-41b22ba4146e'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat rutinitas hemat: なるべく外食を ___ ようにしています。', '{"options": ["しない", "した", "して", "せず"], "translation": "Saya berusaha sebisa mungkin tidak makan di luar.", "sentence_template": "なるべく外食を [blank] ようにしています。"}'::jsonb, '{"selected": "しない"}'::jsonb, 'Bentuk-NAI dari する adalah しない, sehingga menjadi なるべく外食をしないようにしています.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('108b43a6-62e2-5f57-8e1d-16637ca262e1'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya membiasakan diri berjalan kaki ke stasiun setiap pagi."', '{"tokens": ["なりました。", "しています。", "毎朝", "歩いて", "歩く", "ように", "駅まで"], "target_translation": "Saya membiasakan diri berjalan kaki ke stasiun setiap pagi.", "romaji": "Maiasa eki made aruku you ni shite imasu."}'::jsonb, '["毎朝", "駅まで", "歩く", "ように", "しています。"]'::jsonb, 'Bentuk kamus 歩く digabungkan dengan ようにしています untuk menyatakan kebiasaan yang sedang dijaga.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d10d3923-34b2-5d3f-959f-c0f023c1e3af'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha untuk tidak begadang."', '{"tokens": ["夜更かしを", "した", "ように", "しています。", "する", "しない"], "target_translation": "Saya berusaha untuk tidak begadang.", "romaji": "Yofukashi o shinai you ni shite imasu."}'::jsonb, '["夜更かしを", "しない", "ように", "しています。"]'::jsonb, '夜更かしをする (begadang) diubah ke bentuk-NAI menjadi 夜更かしをしない lalu diikuti ようにしています.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('30a3bf8f-affc-588b-b3ae-31760354576e'::uuid, 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'listening', 'listening_choice', 'Apa kebiasaan bahasa Jepang yang dilakukan pembicara di kereta?', '{"audio_text": "通勤の電車の中では、必ず日本のニュースを聞くようにしています。", "options": [{"id": "opt_1", "text": "Membaca manga berbahasa Jepang"}, {"id": "opt_2", "text": "Menulis catatan harian di ponsel"}, {"id": "opt_3", "text": "Mendengarkan berita Jepang setiap berangkat kerja"}, {"id": "opt_4", "text": "Berlatih percakapan dengan teman sekantor"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '日本のニュースを聞くようにしています berarti membiasakan diri mendengarkan berita Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, '786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, 'Simak & Baca: Gaya Hidup di Jepang', 'Simak & Baca', 'n3-u1-dengar-baca', 'play-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1e0c170f-7a5e-597b-83d2-0c26735594fd'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang pembicara usahakan saat membeli makanan di minimarket?', '{"audio_text": "コンビニでお弁当を買うときは、必ずカロリーと塩分を確認するようにしています。", "options": [{"id": "opt_1", "text": "Memilih kotak bekal yang sedang diskon malam hari"}, {"id": "opt_2", "text": "Meminta staf memanaskan makanan lebih lama"}, {"id": "opt_3", "text": "Membeli minuman hangat sebagai pendamping"}, {"id": "opt_4", "text": "Memeriksa kalori dan kadar garam terlebih dahulu"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, 'カロリーと塩分を確認する berarti memeriksa kalori dan kadar garam.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('cbfbe9bb-925b-5c1d-a667-64e9023c1225'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara mulai membawa botol minum sendiri ke kantor?', '{"audio_text": "ゴミを減らすために、毎日家からお茶を入れてマイボトルを持っていくようにしています。", "options": [{"id": "opt_1", "text": "Untuk mengurangi sampah"}, {"id": "opt_2", "text": "Karena air di kantor rasanya aneh"}, {"id": "opt_3", "text": "Karena mesin penjual otomatis sering rusak"}, {"id": "opt_4", "text": "Agar bisa minum kopi panas saat rapat"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'ゴミを減らすために berarti ''demi mengurangi sampah''.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2fda6838-c71a-5b52-8367-27d3a77daf83'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'listening', 'listening_choice', 'Apa saran senior kepada pegawai baru dalam audio ini?', '{"audio_text": "わからないことがあったら、そのままにしないで早めに質問するようにしてください。", "options": [{"id": "opt_1", "text": "Mencatat semua tugas di buku agenda pribadi"}, {"id": "opt_2", "text": "Segera bertanya jika ada hal yang tidak dipahami"}, {"id": "opt_3", "text": "Menyelesaikan pekerjaan sebelum jam makan siang"}, {"id": "opt_4", "text": "Memeriksa email dari klien setiap satu jam"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '早めに質問するようにしてください berarti ''usahakanlah untuk bertanya lebih awal''.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f8cedb34-e623-59a8-a601-f1334191e936'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata penghubung yang tepat: 疲れていても、歯を磨いてから寝る ___ しています。', '{"options": ["ように", "ことに", "ために", "そうに"], "translation": "Meskipun lelah, saya membiasakan diri menyikat gigi dulu sebelum tidur.", "sentence_template": "疲れていても、歯を磨いてから寝る [blank] しています。"}'::jsonb, '{"selected": "ように"}'::jsonb, '～ようにしています menekankan usaha rutin yang dijaga secara sadar.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('b1f21553-732a-5e18-a6f3-1b960e023e77'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi nasihat kesehatan: 目の疲れを防ぐため、一時間ごとに休憩を ___ ようにしてください。', '{"options": ["とる", "とった", "とって", "とります"], "translation": "Untuk mencegah kelelahan mata, usahakanlah mengambil istirahat setiap satu jam.", "sentence_template": "目の疲れを防ぐため、一時間ごとに休憩を [blank] ようにしてください。"}'::jsonb, '{"selected": "とる"}'::jsonb, 'Sebelum ようにしてください digunakan bentuk kamus (休憩をとる).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('eaee3f85-e538-5c81-9c99-b3f429238923'::uuid, '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2'::uuid, NULL, 'reading', 'fill_blank', 'Pilih opsi paling alami: 書類のミスをなくすため、提出前に二回 ___ ようにしています。', '{"options": ["見直す", "見直した", "見直して", "見直そう"], "translation": "Demi menghilangkan kesalahan dokumen, saya membiasakan diri memeriksa ulang dua kali sebelum mengumpulkan.", "sentence_template": "書類のミスをなくすため、提出前に二回 [blank] ようにしています。"}'::jsonb, '{"selected": "見直す"}'::jsonb, '見直す (minaosu) berarti memeriksa kembali; dipakai dalam bentuk kamus sebelum ようにしています.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, '786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, 'Bicara & Rakit Kalimat Kebiasaan', 'Bicara & Rakit', 'n3-u1-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3bb04865-74d2-55a1-926f-5d503a0cc2ad'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya membiasakan diri minum dua liter air setiap hari."', '{"display_text": "毎日水を二リットル飲むようにしています。", "romaji": "Mainichi mizu o ni rittoru nomu you ni shite imasu.", "phonetic_breakdown": ["mai-ni-chi", "mi-zu o", "ni rit-to-ru", "no-mu", "you ni", "shi-te i-ma-su"]}'::jsonb, '{"expected_transcript": "毎日水を二リットル飲むようにしています。"}'::jsonb, 'Perhatikan pelafalan vokal panjang pada ように (you ni) dan konsonan ganda pada リットル (rittoru).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d156af82-91b7-5667-82a6-794b3059d0e3'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Usahakanlah untuk tidak melupakan kartu identitas."', '{"display_text": "社員証を忘れないようにしてください。", "romaji": "Shainshou o wasurenai you ni shite kudasai.", "phonetic_breakdown": ["sha-in-shou o", "wa-su-re-na-i", "you ni", "shi-te", "ku-da-sa-i"]}'::jsonb, '{"expected_transcript": "社員証を忘れないようにしてください。"}'::jsonb, '社員証 (shainshou) berarti kartu tanda pegawai. Pola ～ないようにしてください digunakan untuk imbauan sopan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2947e56e-4de7-5028-a667-3ed7562d68ad'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai bulan ini saya berusaha memakai bahasa Jepang di kantor."', '{"display_text": "今月から職場で日本語を使うようにしています。", "romaji": "Kongetsu kara shokuba de nihongo o tsukau you ni shite imasu.", "phonetic_breakdown": ["kon-ge-tsu ka-ra", "sho-ku-ba de", "ni-hon-go o", "tsu-ka-u", "you ni", "shi-te i-ma-su"]}'::jsonb, '{"expected_transcript": "今月から職場で日本語を使うようにしています。"}'::jsonb, '職場 (shokuba) berarti tempat kerja. Ucapkan 使うように secara mengalir.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d5f6d06f-e849-50f4-ac0b-56a560b581a6'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha tidur sebelum jam sebelas malam."', '{"tokens": ["しています。", "寝る", "ように", "夜十一時前に", "寝て", "寝た"], "target_translation": "Saya berusaha tidur sebelum jam sebelas malam.", "romaji": "Yoru juuichiji mae ni neru you ni shite imasu."}'::jsonb, '["夜十一時前に", "寝る", "ように", "しています。"]'::jsonb, 'Gunakan bentuk kamus 寝る sebelum ようにしています.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e4342fbc-14c9-5cf2-8658-f288b01e5ff6'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Usahakan untuk mencatat hal penting saat rapat."', '{"tokens": ["してください。", "メモした", "メモする", "大事なことを", "なります。", "ように", "会議のときは"], "target_translation": "Usahakan untuk mencatat hal penting saat rapat.", "romaji": "Kaigi no toki wa daijina koto o memo suru you ni shite kudasai."}'::jsonb, '["会議のときは", "大事なことを", "メモする", "ように", "してください。"]'::jsonb, 'メモする (mencatat) dalam bentuk kamus diikuti ようにしてください membentuk instruksi sopan.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('676641d9-7742-5f08-8b3f-8ccb0c98cb83'::uuid, 'b9417a14-d041-510d-9efe-e8e043b82fcb'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha tidak menggunakan ponsel sebelum tidur."', '{"tokens": ["見る", "見ます", "ように", "寝る前に", "しています。", "スマホを", "見ない"], "target_translation": "Saya berusaha tidak menggunakan ponsel sebelum tidur.", "romaji": "Neru mae ni sumaho o minai you ni shite imasu."}'::jsonb, '["寝る前に", "スマホを", "見ない", "ように", "しています。"]'::jsonb, 'Bentuk-NAI 見ない + ようにしています menyatakan usaha konsisten menghindari layar ponsel sebelum tidur.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, '786d613d-e0fe-5813-ad82-e63bc2dd7a27'::uuid, 'Evaluasi Unit 1: Kebiasaan & Target', 'Tes Unit 1', 'n3-u1-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('26800879-4037-59f1-8872-76639bceb5b2'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk paling tepat: エレベーターを使わず、階段で ___ ようにしています。', '{"options": ["上がる", "上がった", "上がって", "上がろう"], "translation": "Tanpa memakai lift, saya membiasakan diri naik lewat tangga.", "sentence_template": "エレベーターを使わず、階段で [blank] ようにしています。"}'::jsonb, '{"selected": "上がる"}'::jsonb, 'Bentuk kamus 上がる digunakan sebelum ようにしています.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fffc0b3f-13a6-5cd5-b52f-26cf1652b115'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi imbauan kantor: 個人情報が外部に ___ ようにしてください。', '{"options": ["漏れない", "漏れる", "漏れた", "漏れて"], "translation": "Usahakanlah agar data pribadi tidak bocor ke pihak luar.", "sentence_template": "個人情報が外部に [blank] ようにしてください。"}'::jsonb, '{"selected": "漏れない"}'::jsonb, '漏れる (moreru = bocor) diubah ke bentuk-NAI 漏れない agar bermakna ''tidak bocor''.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('be7b77d0-bdba-5194-8bdb-d180ff157fc0'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'listening', 'listening_choice', 'Apa yang dilakukan pembicara demi menghemat uang bulanan?', '{"audio_text": "節約のために、平日は自分で弁当を作って会社へ持っていくようにしています。", "options": [{"id": "opt_1", "text": "Berjalan kaki pulang dari kantor setiap sore"}, {"id": "opt_2", "text": "Berbelanja bahan makanan hanya saat akhir pekan"}, {"id": "opt_3", "text": "Membuat bekal sendiri pada hari kerja"}, {"id": "opt_4", "text": "Tidak membeli kopi di kafe dekat stasiun"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '平日は自分で弁当を作って会社へ持っていく berarti membuat bekal sendiri dan membawanya ke kantor di hari kerja.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6eb9a252-969e-5dd9-b972-2b4756b4cc32'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara datang 10 menit lebih awal sebelum jam kerja?', '{"audio_text": "慌てないように、始業時間の十分前には席に着くようにしています。", "options": [{"id": "opt_1", "text": "Agar bisa sarapan dengan tenang di kantin"}, {"id": "opt_2", "text": "Agar bisa mengobrol lebih lama dengan rekan kerja"}, {"id": "opt_3", "text": "Karena bus yang dinaiki selalu tiba terlalu cepat"}, {"id": "opt_4", "text": "Agar tidak terburu-buru saat jam kerja dimulai"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '慌てないように berarti ''agar tidak panik / terburu-buru''.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ab76b573-304b-5e82-86c2-aa05622fdf6a'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha mengecek prakiraan cuaca setiap pagi."', '{"tokens": ["毎朝", "確認する", "天気予報を", "確認して", "ように", "しています。", "確認した"], "target_translation": "Saya berusaha mengecek prakiraan cuaca setiap pagi.", "romaji": "Maiasa tenki yohou o kakunin suru you ni shite imasu."}'::jsonb, '["毎朝", "天気予報を", "確認する", "ように", "しています。"]'::jsonb, '天気予報を確認する (mengecek prakiraan cuaca) + ようにしています.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0cbf4f0b-c4d6-58de-bbdb-5d08ac43650d'::uuid, '7eda7366-e41d-5329-b4b6-4cc012dd3b55'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-001' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya membiasakan diri membalas email di hari yang sama."', '{"display_text": "メールはその日のうちに返信するようにしています。", "romaji": "Meeru wa sono hi no uchi ni henshin suru you ni shite imasu.", "phonetic_breakdown": ["mee-ru wa", "so-no hi no u-chi ni", "hen-shin su-ru", "you ni", "shi-te i-ma-su"]}'::jsonb, '{"expected_transcript": "メールはその日のうちに返信するようにしています。"}'::jsonb, '返信する (henshin suru) berarti membalas pesan/email. Kalimat ini sangat berguna dalam etika kerja Jepang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, v_level_id, 'Keputusan Resmi (～ことになる)', 'Kuasai pola ～ことになる dan ～ことになっている untuk menyampaikan pengumuman kantor, penugasan, dan aturan organisasi.', 'curriculum', 2);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, 'cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, 'Kosakata Kantor, Penugasan & Pengumuman', 'Kosakata Kantor', 'n3-u2-kosakata', 'briefcase', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1950b039-1243-5123-a5a8-dd2767d7b2f7'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat penugasan kerja: 来月から大阪支社へ ___ します。', '{"options": ["転勤", "欠勤", "出勤", "残業"], "translation": "Mulai bulan depan saya dipindahtugaskan ke cabang Osaka.", "sentence_template": "来月から大阪支社へ [blank] します。"}'::jsonb, '{"selected": "転勤"}'::jsonb, '転勤 (tenkin) berarti mutasi/pindah tugas ke cabang lain. 出勤 (masuk kerja), 欠勤 (absen kerja), 残業 (lembur).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('89f5eee1-5d55-5e1a-8942-51e8ec932cf9'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk rapat kantor: 今日の午後は大切な ___ があります。', '{"options": ["打ち合わせ", "問い合わせ", "待ち合わせ", "組み合わせ"], "translation": "Siang ini ada rapat koordinasi yang penting.", "sentence_template": "今日の午後は大切な [blank] があります。"}'::jsonb, '{"selected": "打ち合わせ"}'::jsonb, '打ち合わせ (uchiawase) berarti rapat koordinasi/persiapan kerja.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f10bab5d-b29b-5915-85b5-186e3489893a'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi: 会議の開始時間が変更になったので、全員に ___ してください。', '{"options": ["連絡", "延期", "中止", "参加"], "translation": "Karena jam mulai rapat berubah, tolong beri tahu semua orang.", "sentence_template": "会議の開始時間が変更になったので、全員に [blank] してください。"}'::jsonb, '{"selected": "連絡"}'::jsonb, '連絡する (renraku suru) berarti menghubungi atau memberi tahu.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('79df3b4d-7dd1-5ecb-bbcb-fe327b8e9f3d'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kosakata yang sesuai: 大雨のため、屋外イベントは来週へ ___ されました。', '{"options": ["延期", "開始", "決定", "担当"], "translation": "Karena hujan deras, acara luar ruang ditunda ke minggu depan.", "sentence_template": "大雨のため、屋外イベントは来週へ [blank] されました。"}'::jsonb, '{"selected": "延期"}'::jsonb, '延期 (enki) berarti penundaan jadwal ke waktu lain.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('894c6f26-1844-51d2-a711-674a5d932464'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'listening', 'listening_choice', 'Di mana tempat kerja baru pembicara mulai bulan April?', '{"audio_text": "四月から東京の本社で新しいプロジェクトを担当します。", "options": [{"id": "opt_1", "text": "Di kantor pusat Tokyo"}, {"id": "opt_2", "text": "Di kantor cabang Nagoya"}, {"id": "opt_3", "text": "Di pabrik dekat bandara"}, {"id": "opt_4", "text": "Bekerja penuh dari rumah"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '東京の本社 berarti kantor pusat Tokyo, dan 担当します berarti menjadi penanggung jawab.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0d4cd5a2-82cd-558d-8720-3ac2c1011b6b'::uuid, '39d94c02-bb2c-5c68-a2e8-14f26bf6f132'::uuid, NULL, 'listening', 'listening_choice', 'Apa isi pengumuman mengenai jam kerja hari Jumat?', '{"audio_text": "今週の金曜日は社内研修があるため、通常より一時間早く業務を終了します。", "options": [{"id": "opt_1", "text": "Hari Jumat kantor libur penuh"}, {"id": "opt_2", "text": "Pekerjaan berakhir satu jam lebih awal karena pelatihan internal"}, {"id": "opt_3", "text": "Seluruh staf harus lembur satu jam untuk pelatihan"}, {"id": "opt_4", "text": "Pelatihan internal dipindahkan ke hari Senin pagi"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '社内研修があるため、通常より一時間早く業務を終了します berarti berakhir satu jam lebih awal karena pelatihan internal.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, 'cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, 'Pola ～ことになる & ～ことになっている', 'Pola Koto ni Naru', 'n3-u2-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2a1aae16-ea68-51f7-bc45-486209f9e37a'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi pengumuman penugasan: 来月、福岡へ出張 ___ ことになりました。', '{"options": ["する", "した", "して", "します"], "translation": "Diputuskan bahwa bulan depan saya akan dinas ke Fukuoka.", "sentence_template": "来月、福岡へ出張 [blank] ことになりました。"}'::jsonb, '{"selected": "する"}'::jsonb, 'Pola ～ことになる memakai bentuk kamus (出張する) atau bentuk-NAI sebelum ことになりました.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0828e622-2708-535d-8958-136dc174c676'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk aturan kantor: この会議室では飲食 ___ ことになっています。', '{"options": ["しない", "した", "して", "せず"], "translation": "Di ruang rapat ini aturannya tidak boleh makan dan minum.", "sentence_template": "この会議室では飲食 [blank] ことになっています。"}'::jsonb, '{"selected": "しない"}'::jsonb, 'Bentuk-NAI + ことになっている menyatakan aturan atau ketetapan yang melarang sesuatu.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('63d48151-82f3-5e5b-ac5d-dec53187afd5'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi jadwal rutin: 毎週月曜日に進捗報告を ___ ことになっています。', '{"options": ["提出する", "提出した", "提出して", "提出します"], "translation": "Setiap hari Senin dijadwalkan untuk menyerahkan laporan progres.", "sentence_template": "毎週月曜日に進捗報告を [blank] ことになっています。"}'::jsonb, '{"selected": "提出する"}'::jsonb, '～ことになっています menyatakan jadwal atau prosedur tetap organisasi; verba sebelumnya berbentuk kamus.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fecf421e-795b-5ba4-abb6-ba26365a012d'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa rapat besok dilaksanakan secara daring."', '{"tokens": ["明日の会議は", "しました。", "オンラインで", "行う", "ことに", "行った", "なりました。"], "target_translation": "Diputuskan bahwa rapat besok dilaksanakan secara daring.", "romaji": "Ashita no kaigi wa onrain de okonau koto ni narimashita."}'::jsonb, '["明日の会議は", "オンラインで", "行う", "ことに", "なりました。"]'::jsonb, '行う (melaksanakan) + ことになりました menandakan keputusan resmi pihak kantor/panitia.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4dd8f2af-e612-557d-87d3-c99f95b37e42'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Aturannya kita wajib memakai kartu pegawai di dalam gedung."', '{"tokens": ["しています。", "つけた", "ことに", "つける", "なっています。", "建物の中では", "社員証を"], "target_translation": "Aturannya kita wajib memakai kartu pegawai di dalam gedung.", "romaji": "Tatemono no naka de wa shainshou o tsukeru koto ni natte imasu."}'::jsonb, '["建物の中では", "社員証を", "つける", "ことに", "なっています。"]'::jsonb, '～ことになっています digunakan untuk menjelaskan aturan yang berlaku umum.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7b06b1d3-edac-5019-aa62-a75ff72fa0ef'::uuid, '6aa10a9c-a309-5afe-87f3-303a1d9e4d39'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'listening', 'listening_choice', 'Keputusan apa yang baru diterima pembicara?', '{"audio_text": "急な話ですが、来週から新しいチームのリーダーを任されることになりました。", "options": [{"id": "opt_1", "text": "Ia diminta pindah ke divisi pemasaran"}, {"id": "opt_2", "text": "Ia dibebaskan dari tugas lembur minggu depan"}, {"id": "opt_3", "text": "Ia dipercaya menjadi ketua tim baru mulai minggu depan"}, {"id": "opt_4", "text": "Ia harus mengikuti pelatihan di luar negeri"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '新しいチームのリーダーを任されることになりました berarti diputuskan bahwa ia dipercaya menjadi pemimpin tim baru.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, 'cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, 'Simak & Baca: Prosedur & Perubahan Jadwal', 'Prosedur & Jadwal', 'n3-u2-dengar-baca', 'calendar-blank', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c41e6180-26e3-57e3-8384-cbeb780a5e1f'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana aturan pengajuan cuti di perusahaan tersebut?', '{"audio_text": "有給休暇を取る場合は、一週間前までにシステムから申請することになっています。", "options": [{"id": "opt_1", "text": "Cukup mengirim pesan singkat kepada rekan tim"}, {"id": "opt_2", "text": "Harus meminta izin lisan pada pagi hari cuti"}, {"id": "opt_3", "text": "Hanya boleh diajukan pada akhir bulan"}, {"id": "opt_4", "text": "Harus diajukan melalui sistem paling lambat seminggu sebelumnya"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '一週間前までにシステムから申請することになっています berarti aturannya mengajukan lewat sistem maksimal 1 minggu sebelumnya.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7e1c4675-ad0d-5d13-8ece-09e27cb36e99'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang terjadi pada jadwal kunjungan klien besok?', '{"audio_text": "先方の都合により、明日の訪問は来週の水曜日に変更することになりました。", "options": [{"id": "opt_1", "text": "Diubah menjadi hari Rabu minggu depan"}, {"id": "opt_2", "text": "Dibatalkan sepenuhnya tanpa jadwal pengganti"}, {"id": "opt_3", "text": "Dimajukan menjadi sore ini"}, {"id": "opt_4", "text": "Dipindahkan ke ruang rapat lantai lima"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '来週の水曜日に変更することになりました berarti diputuskan berubah ke hari Rabu minggu depan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('357edba5-cc08-51e1-84dc-bcf86cbea4a8'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang harus dilakukan pengunjung saat masuk ke ruang server?', '{"audio_text": "セキュリティのため、入室の際は受付で名前を記入することになっています。", "options": [{"id": "opt_1", "text": "Menitipkan tas di loker lantai dasar"}, {"id": "opt_2", "text": "Menuliskan nama di meja resepsionis saat masuk"}, {"id": "opt_3", "text": "Menunggu konfirmasi tertulis dari direktur"}, {"id": "opt_4", "text": "Memakai sepatu khusus laboratorium"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '受付で名前を記入することになっています berarti aturannya menuliskan nama di resepsionis.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1659715b-5271-594c-bbf2-5553b733fe78'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih akhiran yang tepat untuk keputusan luar: 来年から制服が新しく ___ 。', '{"options": ["なることになりました", "なることにしました", "なったことになりました", "なるようになりました"], "translation": "Diputuskan bahwa mulai tahun depan seragamnya akan menjadi baru.", "sentence_template": "来年から制服が新しく [blank] 。"}'::jsonb, '{"selected": "なることになりました"}'::jsonb, 'Perubahan seragam adalah keputusan organisasi/perusahaan, sehingga tepat memakai ～ことになりました (bukan ～ことにしました yang keputusan pribadi).', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3f6ed78d-b792-5fd2-8c97-3afa3728a544'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi aturan asrama: この寮では夜十時以降、洗濯機を ___ ことになっています。', '{"options": ["使わない", "使う", "使った", "使って"], "translation": "Di asrama ini aturannya tidak boleh memakai mesin cuci setelah jam 10 malam.", "sentence_template": "この寮では夜十時以降、洗濯機を [blank] ことになっています。"}'::jsonb, '{"selected": "使わない"}'::jsonb, 'Aturan larangan memakai Bentuk-NAI (使わない) + ことになっています.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('997eca14-a4a8-5ba9-9ae3-e67703177fd9'::uuid, 'f6f88020-c0f8-5335-84f9-0f74c479fb4b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman proyek: 予算の関係で、今回の計画は見直す ___ なりました。', '{"options": ["ことに", "ように", "ものに", "ところに"], "translation": "Karena masalah anggaran, diputuskan bahwa rencana kali ini akan ditinjau ulang.", "sentence_template": "予算の関係で、今回の計画は見直す [blank] なりました。"}'::jsonb, '{"selected": "ことに"}'::jsonb, '見直すことになりました berarti diputuskan untuk meninjau ulang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, 'cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, 'Bicara & Rakit Pengumuman Kerja', 'Bicara Pengumuman', 'n3-u2-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5151b84f-bfcb-52bc-8b61-6e7283864500'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan menikah bulan depan."', '{"display_text": "来月結婚することになりました。", "romaji": "Raigetsu kekkon suru koto ni narimashita.", "phonetic_breakdown": ["ra-i-ge-tsu", "kek-kon su-ru", "ko-to ni", "na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "来月結婚することになりました。"}'::jsonb, 'Dalam bahasa Jepang, ～ことになりました sering dipakai untuk mengumumkan pernikahan secara rendah hati seolah hasil kesepakatan bersama.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bb98a2fe-4f37-5864-8683-e85625508c93'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapat dijadwalkan dimulai pada pukul dua."', '{"display_text": "会議は二時から始まることになっています。", "romaji": "Kaigi wa niji kara hajimaru koto ni natte imasu.", "phonetic_breakdown": ["ka-i-gi wa", "ni-ji ka-ra", "ha-ji-ma-ru", "ko-to ni", "nat-te i-ma-su"]}'::jsonb, '{"expected_transcript": "会議は二時から始まることになっています。"}'::jsonb, '～ことになっています menunjukkan jadwal yang sudah ditetapkan sebelumnya.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('9221ac87-fad8-5322-9788-2190f5c0e192'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan menjadi penanggung jawab klien ini."', '{"display_text": "私がこちらのお客様を担当することになりました。", "romaji": "Watashi ga kochira no okyakusama o tantou suru koto ni narimashita.", "phonetic_breakdown": ["wa-ta-shi ga", "ko-chi-ra no", "o-kya-ku-sa-ma o", "tan-tou su-ru", "ko-to ni", "na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "私がこちらのお客様を担当することになりました。"}'::jsonb, 'Ungkapan sopan yang sangat lazim saat memperkenalkan diri sebagai PIC baru kepada klien.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('672ba820-331b-5113-96ed-4e75b0c1bb55'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa mulai bulan depan saya bekerja di Tokyo."', '{"tokens": ["ことに", "なりました。", "働いて", "来月から", "東京で", "働く", "しました。"], "target_translation": "Diputuskan bahwa mulai bulan depan saya bekerja di Tokyo.", "romaji": "Raigetsu kara Toukyou de hataraku koto ni narimashita."}'::jsonb, '["来月から", "東京で", "働く", "ことに", "なりました。"]'::jsonb, '働く (bentuk kamus) + ことになりました menyatakan penempatan kerja yang diputuskan kantor.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('37bb58ca-7213-57fc-83a5-7773c534a654'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Di perpustakaan ini aturannya dilarang menelepon."', '{"tokens": ["なっています。", "する", "ことに", "ように", "この図書館では", "電話を", "しない"], "target_translation": "Di perpustakaan ini aturannya dilarang menelepon.", "romaji": "Kono toshokan de wa denwa o shinai koto ni natte imasu."}'::jsonb, '["この図書館では", "電話を", "しない", "ことに", "なっています。"]'::jsonb, '電話をしない + ことになっています menyatakan aturan larangan yang berlaku.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e6577185-d597-5a1e-bda9-fca17391f3e7'::uuid, 'ba66eaca-627c-54c6-8869-e45b8070cb2e'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa acara hari Minggu dibatalkan."', '{"tokens": ["なる", "ことに", "なった", "中止に", "なりました。", "日曜日のイベントは", "します。"], "target_translation": "Diputuskan bahwa acara hari Minggu dibatalkan.", "romaji": "Nichiyoubi no ibento wa chuushi ni naru koto ni narimashita."}'::jsonb, '["日曜日のイベントは", "中止に", "なる", "ことに", "なりました。"]'::jsonb, '中止になる (menjadi batal) + ことになりました.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, 'cbfa037b-0a6f-5993-8fd1-1d87ccdd0486'::uuid, 'Evaluasi Unit 2: Keputusan & Aturan', 'Tes Unit 2', 'n3-u2-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0dcc68e0-cb55-5fec-961a-ea765bfbbe38'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'reading', 'fill_blank', 'Pilih pola yang tepat: 来期から新しい評価制度が導入 ___ ことになりました。', '{"options": ["される", "された", "されて", "します"], "translation": "Diputuskan bahwa mulai periode depan sistem penilaian baru akan diterapkan.", "sentence_template": "来期から新しい評価制度が導入 [blank] ことになりました。"}'::jsonb, '{"selected": "される"}'::jsonb, '導入される (diterapkan, pasif bentuk kamus) diikuti ことになりました.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ead5b1bf-605d-5d89-a740-938751dc7f92'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi aturan apartemen: 燃えるゴミは火曜日と金曜日に ___ ことになっています。', '{"options": ["出す", "出した", "出して", "出します"], "translation": "Aturannya sampah yang bisa dibakar dibuang pada hari Selasa dan Jumat.", "sentence_template": "燃えるゴミは火曜日と金曜日に [blank] ことになっています。"}'::jsonb, '{"selected": "出す"}'::jsonb, 'ゴミを出す (membuang sampah) dalam bentuk kamus sebelum ことになっています.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('478647c7-a79d-5ad1-ad10-63018afefa97'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'listening', 'listening_choice', 'Apa aturan kantor terkait jam istirahat makan siang?', '{"audio_text": "昼休みは十二時から一時までですが、忙しい日は交代で休むことになっています。", "options": [{"id": "opt_1", "text": "Jam istirahat selalu dimulai pukul sebelas"}, {"id": "opt_2", "text": "Pegawai dilarang keluar gedung saat jam istirahat"}, {"id": "opt_3", "text": "Pada hari sibuk pegawai beristirahat secara bergantian"}, {"id": "opt_4", "text": "Jika sibuk jam istirahat ditiadakan dan diganti uang lembur"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '交代で休むことになっています berarti aturannya beristirahat secara bergantian.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e39c3ada-6106-5e19-86c6-6521702ebe12'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'listening', 'listening_choice', 'Mengapa jadwal pengiriman barang berubah?', '{"audio_text": "工場の点検が入ったため、商品の発送は来週の月曜日に行うことになりました。", "options": [{"id": "opt_1", "text": "Karena pesanan dari pelanggan dibatalkan"}, {"id": "opt_2", "text": "Karena alamat pengiriman belum lengkap"}, {"id": "opt_3", "text": "Karena gudang sedang pindah lokasi"}, {"id": "opt_4", "text": "Karena ada jadwal inspeksi pabrik"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '工場の点検が入ったため berarti karena ada inspeksi/pengecekan pabrik.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4af0c137-3d5e-5d91-ba4b-5895eceb25b7'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Aturannya laporan dikumpulkan setiap hari Jumat."', '{"tokens": ["しています。", "報告書を", "ことに", "毎週金曜日に", "なっています。", "出す", "出した"], "target_translation": "Aturannya laporan dikumpulkan setiap hari Jumat.", "romaji": "Maishuu kinyoubi ni houkokusho o dasu koto ni natte imasu."}'::jsonb, '["毎週金曜日に", "報告書を", "出す", "ことに", "なっています。"]'::jsonb, '報告書を出す + ことになっています menyatakan kewajiban rutin sesuai prosedur.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7bd002d0-88b9-5cdb-93bb-e2dde6ea7473'::uuid, '561c2619-0aa5-55d6-ac2d-b46ba2d51e23'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-002' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan belajar di universitas di Jepang."', '{"display_text": "日本の大学に留学することになりました。", "romaji": "Nihon no daigaku ni ryuugaku suru koto ni narimashita.", "phonetic_breakdown": ["ni-hon no", "da-i-ga-ku ni", "ryuu-ga-ku su-ru", "ko-to ni", "na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "日本の大学に留学することになりました。"}'::jsonb, '留学する (ryuugaku suru) berarti studi ke luar negeri. Cocok dipakai saat hasil seleksi beasiswa/kampus sudah resmi.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, v_level_id, 'Berkat Dukungan (～おかげで)', 'Ungkapkan rasa syukur dan pencapaian positif berkat bantuan orang lain atau kondisi yang mendukung dengan pola ～おかげで.', 'curriculum', 3);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, 'b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, 'Kosakata Pencapaian, Bantuan & Kerja Tim', 'Kosakata Pencapaian', 'n3-u3-kosakata', 'users-three', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a012c098-def5-5e8c-b5c5-cb6f4aa1ff46'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kelulusan: 半年間の努力が実り、無事に試験に ___ しました。', '{"options": ["合格", "失敗", "欠席", "中止"], "translation": "Usaha selama setengah tahun membuahkan hasil dan saya lulus ujian dengan baik.", "sentence_template": "半年間の努力が実り、無事に試験に [blank] しました。"}'::jsonb, '{"selected": "合格"}'::jsonb, '合格する (goukaku suru) berarti lulus ujian.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('75a5ea64-c5e8-5fe7-a4ba-afdddf79d548'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk dukungan tim: 先輩の丁寧な ___ がとても役に立ちました。', '{"options": ["指導", "反対", "不満", "誤解"], "translation": "Bimbingan yang telaten dari senior sangat bermanfaat.", "sentence_template": "先輩の丁寧な [blank] がとても役に立ちました。"}'::jsonb, '{"selected": "指導"}'::jsonb, '指導 (shidou) berarti bimbingan atau arahan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('490e9684-d1aa-55d6-9fdf-6768f8d754c9'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pemulihan: しっかり休んだので、体調がすっかり ___ しました。', '{"options": ["回復", "悪化", "減少", "延長"], "translation": "Karena beristirahat dengan baik, kondisi tubuh saya pulih sepenuhnya.", "sentence_template": "しっかり休んだので、体調がすっかり [blank] しました。"}'::jsonb, '{"selected": "回復"}'::jsonb, '回復する (kaifuku suru) berarti pulih/membaik. 悪化 (memburuk) adalah lawannya.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('63a2904b-dde0-5352-8b69-6c29e41fd148'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk kerja sama: チーム全員の ___ があってプロジェクトが成功しました。', '{"options": ["協力", "競争", "負担", "請求"], "translation": "Dengan adanya kerja sama seluruh tim, proyeknya berhasil.", "sentence_template": "チーム全員の [blank] があってプロジェクトが成功しました。"}'::jsonb, '{"selected": "協力"}'::jsonb, '協力 (kyouryoku) berarti kerja sama.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('19394f69-9f45-5825-92a3-79c9af6b841f'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang berhasil dicapai pembicara bulan ini?', '{"audio_text": "同僚に手伝ってもらった結果、期限より二日早く資料を完成させることができました。", "options": [{"id": "opt_1", "text": "Menyelesaikan materi dua hari lebih cepat dari tenggat"}, {"id": "opt_2", "text": "Mendapatkan promosi jabatan di kantor cabang"}, {"id": "opt_3", "text": "Menghadiri seminar internasional di Kyoto"}, {"id": "opt_4", "text": "Memperpanjang tenggat proyek selama dua hari"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '期限より二日早く資料を完成させることができました berarti menyelesaikan dokumen dua hari lebih awal dari tenggat.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4fe0f273-afe7-5cb3-8c92-ce3834be3287'::uuid, '2bbc5a39-c69f-54c8-8164-3f542be0027b'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa berterima kasih kepada tetangganya?', '{"audio_text": "引っ越してきたばかりの頃、隣の方にゴミの分別や買い物の場所を親切に教えていただきました。", "options": [{"id": "opt_1", "text": "Karena tetangganya membantu mengangkat perabot berat"}, {"id": "opt_2", "text": "Karena diberi tahu cara memilah sampah dan tempat belanja"}, {"id": "opt_3", "text": "Karena diundang makan malam setiap akhir pekan"}, {"id": "opt_4", "text": "Karena dipinjami sepeda untuk pergi ke stasiun"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, 'ゴミの分別や買い物の場所を親切に教えていただきました berarti diberi tahu dengan ramah tentang pemilahan sampah dan tempat belanja.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, 'b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, 'Pola ～おかげで & ～おかげだ', 'Pola Okage de', 'n3-u3-pola-utama', 'sparkle', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('153c2423-bd40-57c6-a7a6-5e7b38edf941'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 先生 ___ おかげで、日本語が上達しました。', '{"options": ["の", "な", "に", "を"], "translation": "Berkat guru, bahasa Jepang saya berkembang pesat.", "sentence_template": "先生 [blank] おかげで、日本語が上達しました。"}'::jsonb, '{"selected": "の"}'::jsonb, 'Nomina + の + おかげで (先生の + おかげで).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8ac15d49-e424-5b25-836c-3ed8e701b598'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 毎日 ___ おかげで、発表がうまくいきました。', '{"options": ["練習した", "練習して", "練習します", "練習しよう"], "translation": "Berkat berlatih setiap hari, presentasinya berjalan lancar.", "sentence_template": "毎日 [blank] おかげで、発表がうまくいきました。"}'::jsonb, '{"selected": "練習した"}'::jsonb, 'Sebelum おかげで digunakan bentuk biasa; untuk kejadian yang sudah dilakukan gunakan bentuk-TA (練習した).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('cc0c9d58-dbd0-5896-8085-cb768c8a3071'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk kata sifat-NA yang tepat: 天気が ___ おかげで、富士山がきれいに見えました。', '{"options": ["よかった", "いいな", "よくて", "よかったです"], "translation": "Berkat cuaca yang cerah, Gunung Fuji terlihat dengan jelas.", "sentence_template": "天気が [blank] おかげで、富士山がきれいに見えました。"}'::jsonb, '{"selected": "よかった"}'::jsonb, 'Bentuk biasa lampau dari いい adalah よかった, sehingga menjadi 天気がよかったおかげで.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f4bce04d-cd59-5d89-8a08-fd554b969e03'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berkat senior, saya cepat terbiasa dengan pekerjaan."', '{"tokens": ["慣れます。", "せいで、", "慣れました。", "仕事に", "先輩の", "おかげで、", "早く"], "target_translation": "Berkat senior, saya cepat terbiasa dengan pekerjaan.", "romaji": "Senpai no okage de, shigoto ni hayaku naremashita."}'::jsonb, '["先輩の", "おかげで、", "仕事に", "早く", "慣れました。"]'::jsonb, '先輩のおかげで menyatakan rasa terima kasih atas bantuan senior.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('652ecbd8-1fbc-54f6-8e60-1fc76129b97c'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berkat obat ini, demam saya sudah turun."', '{"tokens": ["上がりました。", "この薬の", "熱が", "下がりました。", "おかげで、", "な"], "target_translation": "Berkat obat ini, demam saya sudah turun.", "romaji": "Kono kusuri no okage de, netsu ga sagarimashita."}'::jsonb, '["この薬の", "おかげで、", "熱が", "下がりました。"]'::jsonb, 'Nomina この薬 dihubungkan dengan partikel の sebelum おかげで.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('12f89d11-0b62-50d5-b17b-4cd17373a08a'::uuid, '8f60b7f9-c752-5c02-99ae-19d9d9e11958'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'listening', 'listening_choice', 'Apa alasan keberhasilan acara penyambutan menurut pembicara?', '{"audio_text": "皆さんのご協力のおかげで、歓迎会を無事に終えることができました。", "options": [{"id": "opt_1", "text": "Karena anggaran acara ditambah oleh perusahaan"}, {"id": "opt_2", "text": "Karena restorannya sangat dekat dari stasiun"}, {"id": "opt_3", "text": "Berkat kerja sama semua orang"}, {"id": "opt_4", "text": "Karena jumlah tamu lebih sedikit dari perkiraan"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '皆さんのご協力のおかげで berarti ''berkat kerja sama Anda sekalian''.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, 'b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, 'Simak & Baca: Apresiasi & Rasa Syukur', 'Simak Apresiasi', 'n3-u3-dengar-baca', 'chats-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2e2af5df-b303-5a38-a3db-d2df1b6b0dd0'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara tidak ketinggalan kereta pagi ini?', '{"audio_text": "いつもより十五分早く家を出たおかげで、電車の遅延があっても間に合いました。", "options": [{"id": "opt_1", "text": "Karena ia naik taksi dari depan rumah"}, {"id": "opt_2", "text": "Karena jam rapat dimundurkan lima belas menit"}, {"id": "opt_3", "text": "Karena kereta hari ini berjalan lebih cepat"}, {"id": "opt_4", "text": "Karena ia berangkat lima belas menit lebih awal dari biasanya"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, 'いつもより十五分早く家を出たおかげで berarti berkat berangkat 15 menit lebih awal dari biasanya.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e7707d3c-bd2b-5597-bd9f-e686488dffb5'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'listening', 'listening_choice', 'Apa manfaat yang dirasakan pembicara dari aplikasi kamus baru?', '{"audio_text": "便利な辞書アプリを見つけたおかげで、長い記事を読む時間が半分になりました。", "options": [{"id": "opt_1", "text": "Waktu membaca artikel panjang berkurang setengahnya"}, {"id": "opt_2", "text": "Ia bisa menerjemahkan video rapat secara otomatis"}, {"id": "opt_3", "text": "Ia tidak perlu lagi membeli buku teks N3"}, {"id": "opt_4", "text": "Nilai ujian mendengar meningkat dua kali lipat"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '長い記事を読む時間が半分になりました berarti waktu membaca artikel panjang menjadi setengahnya.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a57f36f6-ef09-5784-8543-2714ab9582c6'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana pembicara bisa menemukan dompetnya yang hilang?', '{"audio_text": "駅の係員の方がすぐ調べてくださったおかげで、落とした財布が見つかりました。", "options": [{"id": "opt_1", "text": "Temannya menemukan dompet itu di kafe"}, {"id": "opt_2", "text": "Petugas stasiun segera membantu mencarinya"}, {"id": "opt_3", "text": "Polisi mengantarkan dompetnya ke apartemen"}, {"id": "opt_4", "text": "Ia mengingat kembali tempat terakhir ia duduk"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '駅の係員の方がすぐ調べてくださったおかげで berarti berkat petugas stasiun yang segera memeriksakannya.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('db8a0ee7-7566-5db3-a0f9-ef21c4aeea54'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'reading', 'fill_blank', 'Pilih akhiran kalimat syukur: 今こうして元気に働けるのは、家族の支えの ___ です。', '{"options": ["おかげ", "せい", "ため", "はず"], "translation": "Bisa bekerja dengan sehat seperti sekarang adalah berkat dukungan keluarga.", "sentence_template": "今こうして元気に働けるのは、家族の支えの [blank] です。"}'::jsonb, '{"selected": "おかげ"}'::jsonb, '～のは～のおかげです digunakan untuk menegaskan bahwa hasil baik terjadi berkat sesuatu/seseorang.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('de7796ab-8a10-54a5-b319-1da19bc849fe'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat dengan adjektiva-NA: 部屋が ___ おかげで、勉強に集中できます。', '{"options": ["静かな", "静かの", "静かだ", "静かで"], "translation": "Berkat kamar yang tenang, saya bisa berkonsentrasi belajar.", "sentence_template": "部屋が [blank] おかげで、勉強に集中できます。"}'::jsonb, '{"selected": "静かな"}'::jsonb, 'Kata sifat-NA memakai な sebelum おかげで (静かなおかげで).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2b40a7fb-48b8-5042-b8c2-bab2461db9f1'::uuid, 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159'::uuid, NULL, 'reading', 'fill_blank', 'Pilih ungkapan respons yang paling alami saat ditanya kabar: ___ 、家族みんな元気です。', '{"options": ["おかげさまで", "そのせいで", "それなのに", "それにしては"], "translation": "Berkat doa Anda / Puji syukur, seluruh keluarga sehat.", "sentence_template": "[blank] 、家族みんな元気です。"}'::jsonb, '{"selected": "おかげさまで"}'::jsonb, 'おかげさまで (okagesama de) adalah ungkapan sopan khas Jepang saat menyampaikan kabar baik dengan rendah hati.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, 'b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, 'Bicara & Rakit Ungkapan Terima Kasih', 'Bicara Syukur', 'n3-u3-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6a13a567-57cb-5951-a328-f07ce2434824'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat Anda, saya lulus ujian."', '{"display_text": "おかげさまで、試験に合格しました。", "romaji": "Okagesama de, shiken ni goukaku shimashita.", "phonetic_breakdown": ["o-ka-ge-sa-ma de", "shi-ken ni", "gou-ka-ku", "shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "おかげさまで、試験に合格しました。"}'::jsonb, 'おかげさまで sangat tepat diucapkan ketika melaporkan keberhasilan kepada guru, senior, atau rekan kerja.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2be43d74-e610-571b-85c8-cd5d0b78617b'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat bantuan Tanaka, tugasnya selesai tepat waktu."', '{"display_text": "田中さんが手伝ってくれたおかげで、間に合いました。", "romaji": "Tanaka-san ga tetsudatte kureta okage de, maniai mashita.", "phonetic_breakdown": ["ta-na-ka-san ga", "te-tsu-dat-te ku-re-ta", "o-ka-ge de", "ma-ni-a-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "田中さんが手伝ってくれたおかげで、間に合いました。"}'::jsonb, 'Kombinasi ～てくれた + おかげで menonjolkan rasa terima kasih atas kebaikan orang lain.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2babbf70-73a8-5618-becf-b5405ec6102d'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat tinggal dekat stasiun, berangkat kerja jadi sangat mudah."', '{"display_text": "駅から近いおかげで、通勤がとても楽です。", "romaji": "Eki kara chikai okage de, tsuukin ga totemo raku desu.", "phonetic_breakdown": ["e-ki ka-ra", "chi-ka-i", "o-ka-ge de", "tsuu-kin ga", "to-te-mo", "ra-ku de-su"]}'::jsonb, '{"expected_transcript": "駅から近いおかげで、通勤がとても楽です。"}'::jsonb, 'Kata sifat-I (近い) langsung disambungkan dengan おかげで.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a7d4b71d-4533-52fd-b9a1-6f3df227d917'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berkat mengulang materi setiap hari, saya mengerti tata bahasanya."', '{"tokens": ["わかりました。", "おかげで、", "文法が", "毎日", "復習して", "せいで、", "復習した"], "target_translation": "Berkat mengulang materi setiap hari, saya mengerti tata bahasanya.", "romaji": "Mainichi fukushuu shita okage de, bunpou ga wakarimashita."}'::jsonb, '["毎日", "復習した", "おかげで、", "文法が", "わかりました。"]'::jsonb, '復習した (bentuk biasa lampau) + おかげで menyatakan sebab dari hasil positif.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3308ecec-ba70-57dc-abe5-8071b522289e'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berkat dukungan teman-teman, saya tidak menyerah."', '{"tokens": ["友達の応援の", "せいで、", "応援な", "おかげで、", "すみました。", "あきらめずに"], "target_translation": "Berkat dukungan teman-teman, saya tidak menyerah.", "romaji": "Tomodachi no ouen no okage de, akiramezu ni sumimashita."}'::jsonb, '["友達の応援の", "おかげで、", "あきらめずに", "すみました。"]'::jsonb, 'Nomina 応援 diikuti の lalu おかげで.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('93d714c9-c668-516f-abec-55531cb18103'::uuid, '1e67fa06-5de4-580f-b23f-ada0a0de41a5'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa sehat kembali berkat saran dokter."', '{"tokens": ["せいで、", "元気に", "なりました。", "アドバイスな", "おかげで、", "医者のアドバイスの"], "target_translation": "Saya bisa sehat kembali berkat saran dokter.", "romaji": "Isha no adobaisu no okage de, genki ni narimashita."}'::jsonb, '["医者のアドバイスの", "おかげで、", "元気に", "なりました。"]'::jsonb, '医者のアドバイス (nasihat dokter) + の + おかげで.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, 'b232b58b-bc6a-5799-9aed-addf086ba391'::uuid, 'Evaluasi Unit 3: Berkat & Pencapaian', 'Tes Unit 3', 'n3-u3-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4de204c1-f772-5183-a78b-7fc9e16bbda2'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 早めに ___ おかげで、安いホテルに泊まれました。', '{"options": ["予約した", "予約する", "予約して", "予約します"], "translation": "Berkat memesan lebih awal, saya bisa menginap di hotel murah.", "sentence_template": "早めに [blank] おかげで、安いホテルに泊まれました。"}'::jsonb, '{"selected": "予約した"}'::jsonb, 'Tindakan memesan sudah selesai dilakukan sehingga memakai 予約したおかげで.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('79ae27a7-f325-5f42-82cd-f79a672b9645'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'reading', 'fill_blank', 'Pilih penghubung yang benar: この地域の治安が ___ おかげで、夜でも安心して歩けます。', '{"options": ["いい", "いいな", "よくて", "いいの"], "translation": "Berkat keamanan wilayah ini yang baik, malam hari pun bisa berjalan dengan tenang.", "sentence_template": "この地域の治安が [blank] おかげで、夜でも安心して歩けます。"}'::jsonb, '{"selected": "いい"}'::jsonb, 'Kata sifat-I いい langsung diikuti おかげで tanpa partikel tambahan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1a5b6e1b-77eb-5f6e-9f58-63a40274b05b'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'listening', 'listening_choice', 'Apa yang membuat pembicara cepat akrab dengan lingkungan kantor baru?', '{"audio_text": "部署の皆さんが温かく迎えてくださったおかげで、すぐに職場に馴染むことができました。", "options": [{"id": "opt_1", "text": "Karena kantornya dekat dengan apartemen"}, {"id": "opt_2", "text": "Karena semua pekerjaan sebelumnya sudah ia kuasai"}, {"id": "opt_3", "text": "Karena rekan-rekan divisi menyambutnya dengan hangat"}, {"id": "opt_4", "text": "Karena ia sudah mengenal manajernya sejak kuliah"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '部署の皆さんが温かく迎えてくださったおかげで berarti berkat rekan-rekan divisi menyambut dengan hangat.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f55d99c3-aadf-5e6d-b2aa-8096e4354d06'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara tidak kehujanan saat pulang kerja?', '{"audio_text": "朝、折りたたみ傘をかばんに入れておいたおかげで、濡れずに帰れました。", "options": [{"id": "opt_1", "text": "Karena hujan berhenti sebelum ia keluar kantor"}, {"id": "opt_2", "text": "Karena ia diantar pulang oleh rekan kerja"}, {"id": "opt_3", "text": "Karena ia membeli payung baru di minimarket"}, {"id": "opt_4", "text": "Karena ia sudah memasukkan payung lipat ke tas sejak pagi"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '折りたたみ傘をかばんに入れておいたおかげで berarti berkat sudah menaruh payung lipat di tas.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f3cc11f3-3a67-5c00-ae11-c0c916e71c67'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berkat bimbingan guru, saya lulus wawancara kerja."', '{"tokens": ["先生の指導の", "面接に", "指導な", "合格しました。", "おかげで、", "失敗しました。"], "target_translation": "Berkat bimbingan guru, saya lulus wawancara kerja.", "romaji": "Sensei no shidou no okage de, mensetsu ni goukaku shimashita."}'::jsonb, '["先生の指導の", "おかげで、", "面接に", "合格しました。"]'::jsonb, '先生の指導 (nomina) + の + おかげで menyatakan sebab dari keberhasilan wawancara.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e4c6de7f-bf78-53e9-aa22-ddccfb3b4efc'::uuid, '2a6a4cfa-2ec1-50c0-8139-e4a438839d32'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-003' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat kerja sama semua pihak, acara berjalan sukses."', '{"display_text": "皆さんのおかげで、イベントが大成功しました。", "romaji": "Minasan no okage de, ibento ga daiseikou shimashita.", "phonetic_breakdown": ["mi-na-san no", "o-ka-ge de", "i-ben-to ga", "da-i-se-i-kou", "shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "皆さんのおかげで、イベントが大成功しました。"}'::jsonb, '大成功 (daiseikou) berarti sukses besar. Kalimat penutup yang sangat bagus untuk pidato atau rapat evaluasi.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, v_level_id, 'Akibat & Kendala (～せいで)', 'Sampaikan penyebab kendala transportasi, cuaca buruk, atau masalah teknis secara tepat dengan pola ～せいで dan ～せいか.', 'curriculum', 4);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, 'bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, 'Kosakata Kendala Transportasi & Cuaca', 'Kosakata Kendala', 'n3-u4-kosakata', 'train', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3ff561ba-b11a-5d27-8320-184d9dd69b09'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kereta: 人身事故があり、電車が30分 ___ しています。', '{"options": ["遅延", "到着", "出発", "予約"], "translation": "Terjadi kecelakaan di jalur rel, sehingga kereta mengalami keterlambatan 30 menit.", "sentence_template": "人身事故があり、電車が30分 [blank] しています。"}'::jsonb, '{"selected": "遅延"}'::jsonb, '遅延 (chien) berarti keterlambatan jadwal transportasi umum.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('34ce8489-ac7c-5384-b254-b3cb00a31a56'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk penerbangan: 大雪で飛行機が ___ になりました。', '{"options": ["欠航", "満席", "搭乗", "通過"], "translation": "Karena salju lebat, penerbangan dibatalkan.", "sentence_template": "大雪で飛行機が [blank] になりました。"}'::jsonb, '{"selected": "欠航"}'::jsonb, '欠航 (kekkou) berarti pembatalan penerbangan atau pelayaran kapal.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('57818ce5-008c-58b5-b6a9-bcff3641c4a5'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kondisi tubuh: 昨日は二時間しか寝られず、ひどい ___ です。', '{"options": ["寝不足", "満腹", "健康", "余裕"], "translation": "Kemarin saya hanya bisa tidur dua jam, jadi sangat kurang tidur.", "sentence_template": "昨日は二時間しか寝られず、ひどい [blank] です。"}'::jsonb, '{"selected": "寝不足"}'::jsonb, '寝不足 (nebusoku) berarti kurang tidur.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('199453d9-6587-5454-bace-67d532485afb'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk lalu lintas: 連休の初日なので、高速道路がひどく ___ しています。', '{"options": ["渋滞", "整理", "工事", "案内"], "translation": "Karena hari pertama libur panjang, jalan tol sangat macet.", "sentence_template": "連休の初日なので、高速道路がひどく [blank] しています。"}'::jsonb, '{"selected": "渋滞"}'::jsonb, '渋滞 (juutai) berarti kemacetan lalu lintas.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('099e1744-7144-58b5-bf65-ea715f83f8d9'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'listening', 'listening_choice', 'Masalah teknis apa yang sedang terjadi di kantor?', '{"audio_text": "朝から社内のネットワークに障害が発生し、メールが送れない状態が続いています。", "options": [{"id": "opt_1", "text": "Gangguan jaringan internal sehingga tidak bisa mengirim email"}, {"id": "opt_2", "text": "Listrik di seluruh gedung padam sejak pagi"}, {"id": "opt_3", "text": "Mesin fotokopi rusak karena kertas tersangkut"}, {"id": "opt_4", "text": "Pendingin ruangan di ruang rapat tidak berfungsi"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'ネットワークに障害が発生し、メールが送れない berarti terjadi gangguan jaringan sehingga tidak dapat mengirim email.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d8e10ba1-9dac-50ef-816e-1a1e37309146'::uuid, 'b71e2a85-c9f0-5242-b443-d72a6a75acdb'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa tidur nyenyak semalam?', '{"audio_text": "夜中に外で工事の騒音がひどくて、何度も目が覚めてしまいました。", "options": [{"id": "opt_1", "text": "Karena kamar apartemennya terlalu panas"}, {"id": "opt_2", "text": "Karena suara bising pekerjaan konstruksi di luar pada tengah malam"}, {"id": "opt_3", "text": "Karena ia minum terlalu banyak kopi sebelum tidur"}, {"id": "opt_4", "text": "Karena telepon genggamnya berbunyi terus-menerus"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '工事の騒音がひどくて berarti suara bising konstruksi sangat parah.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, 'bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, 'Pola ～せいで & ～せいか', 'Pola Sei de', 'n3-u4-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('192794e7-051a-54f1-a616-3d047354cc32'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 台風 ___ せいで、出張が中止になりました。', '{"options": ["の", "な", "に", "で"], "translation": "Gara-gara topan, perjalanan dinas dibatalkan.", "sentence_template": "台風 [blank] せいで、出張が中止になりました。"}'::jsonb, '{"selected": "の"}'::jsonb, 'Nomina + の + せいで (台風のせいで) menyatakan penyebab akibat negatif.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bdde92a3-5642-510b-8bae-2a11a05b257a'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat: 昨夜遅くまで ___ せいで、今朝起きられませんでした。', '{"options": ["起きていた", "起きていて", "起きています", "起きよう"], "translation": "Gara-gara terjaga sampai larut malam tadi, pagi ini saya tidak bisa bangun.", "sentence_template": "昨夜遅くまで [blank] せいで、今朝起きられませんでした。"}'::jsonb, '{"selected": "起きていた"}'::jsonb, 'Sebelum せいで digunakan bentuk biasa (起きていた).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fe099d04-f3ed-573a-9b81-4dc5e8d59585'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'reading', 'fill_blank', 'Pilih nuansa dugaan penyebab: 季節の変わり目の ___ 、最近少しだるいです。', '{"options": ["せいか", "おかげで", "はずで", "ように"], "translation": "Entah mungkin karena pergantian musim, belakangan ini badan saya agak lemas.", "sentence_template": "季節の変わり目の [blank] 、最近少しだるいです。"}'::jsonb, '{"selected": "せいか"}'::jsonb, '～せいか berarti ''mungkin karena / entah karena'' saat pembicara tidak 100% yakin atas penyebab kondisi negatif.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1a15f92e-64f4-5b47-b98d-1519bcbd1c42'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara kurang tidur, kepala saya sakit."', '{"tokens": ["頭が", "寝不足な", "おかげで、", "せいで、", "寝不足の", "痛いです。"], "target_translation": "Gara-gara kurang tidur, kepala saya sakit.", "romaji": "Nebusoku no sei de, atama ga itai desu."}'::jsonb, '["寝不足の", "せいで、", "頭が", "痛いです。"]'::jsonb, 'Akibat negatif (sakit kepala) memakai ～のせいで, bukan ～のおかげで.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('654e4dd0-1ec6-5cce-8f65-06d21dc25812'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara kemacetan, saya terlambat rapat."', '{"tokens": ["遅れました。", "おかげで、", "せいで、", "会議に", "間に合いました。", "渋滞の"], "target_translation": "Gara-gara kemacetan, saya terlambat rapat.", "romaji": "Juutai no sei de, kaigi ni okuremashita."}'::jsonb, '["渋滞の", "せいで、", "会議に", "遅れました。"]'::jsonb, '渋滞のせいで (gara-gara macet) + 会議に遅れました (terlambat rapat).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e45fe223-fe5f-56f1-8bf4-9cc90dd5cb0d'::uuid, '32c92f6c-c296-59fe-ac70-97a32a865304'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'listening', 'listening_choice', 'Apa penyebab utama kegagalan pengiriman file menurut pembicara?', '{"audio_text": "通信が不安定だったせいで、添付ファイルが途中で止まってしまいました。", "options": [{"id": "opt_1", "text": "Ukuran dokumen melebihi batas sistem"}, {"id": "opt_2", "text": "Alamat email penerima salah ketik"}, {"id": "opt_3", "text": "Koneksi internet tidak stabil"}, {"id": "opt_4", "text": "Komputer pembicara tiba-tiba kehabisan baterai"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '通信が不安定だったせいで berarti gara-gara koneksi tidak stabil.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, 'bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, 'Simak & Baca: Mengatasi Masalah Sehari-hari', 'Simak Kendala', 'n3-u4-dengar-baca', 'play-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('753e7d1b-d3be-5e7b-ac2f-d4e642eb8883'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa tenggorokannya sakit?', '{"audio_text": "昨日エアコンをつけたまま寝てしまったせいで、朝から喉が痛いです。", "options": [{"id": "opt_1", "text": "Karena terlalu banyak berbicara saat presentasi"}, {"id": "opt_2", "text": "Karena minum air es setelah berolahraga"}, {"id": "opt_3", "text": "Karena udara di luar sangat berdebu"}, {"id": "opt_4", "text": "Karena tertidur dengan AC tetap menyala semalam"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, 'エアコンをつけたまま寝てしまったせいで berarti gara-gara terlanjur tidur dengan AC menyala.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('df71dd2c-f4cd-514a-b7b5-da976c498aeb'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'listening', 'listening_choice', 'Apa dampak kenaikan harga bahan pangan bagi pembicara?', '{"audio_text": "最近物価が上がったせいで、毎月の食費が以前よりずっと増えました。", "options": [{"id": "opt_1", "text": "Biaya makan bulanannya meningkat jauh dibanding sebelumnya"}, {"id": "opt_2", "text": "Ia harus pindah ke apartemen yang lebih kecil"}, {"id": "opt_3", "text": "Restoran favoritnya dekat stasiun terpaksa tutup"}, {"id": "opt_4", "text": "Ia berhenti memasak sendiri di rumah"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '毎月の食費が以前よりずっと増えました berarti biaya makan bulanan naik jauh dibanding dulu.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('27d4126a-7c45-5177-baf3-0afc0f1f2a95'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa jadwal wawancara harus dijadwalkan ulang?', '{"audio_text": "システムの不具合のせいで、オンライン面接の画面が開けなくなってしまいました。", "options": [{"id": "opt_1", "text": "Karena pewawancara sedang cuti sakit"}, {"id": "opt_2", "text": "Karena gangguan sistem membuat layar wawancara daring tidak bisa dibuka"}, {"id": "opt_3", "text": "Karena pelamar salah mencatat tanggal wawancara"}, {"id": "opt_4", "text": "Karena ruang rapat kantor sedang direnovasi"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, 'システムの不具合のせいで berarti gara-gara gangguan/kerusakan sistem.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f10ec618-3231-5a7b-885e-daf29704d159'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'reading', 'fill_blank', 'Pilih akhiran yang tepat: 今回のミスは、確認不足の ___ です。', '{"options": ["せい", "おかげ", "こと", "よう"], "translation": "Kesalahan kali ini adalah akibat kurangnya pengecekan.", "sentence_template": "今回のミスは、確認不足の [blank] です。"}'::jsonb, '{"selected": "せい"}'::jsonb, '～のせいです digunakan di akhir kalimat untuk menegaskan sumber kesalahan/akibat buruk.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d65ecf91-bb87-58db-9b3f-ed83b0000db0'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi dengan kata sifat-I: 説明が ___ せいで、参加者が混乱してしまいました。', '{"options": ["わかりにくかった", "わかりにくくて", "わかりにくいな", "わかりにくいです"], "translation": "Gara-gara penjelasannya sulit dipahami, para peserta menjadi bingung.", "sentence_template": "説明が [blank] せいで、参加者が混乱してしまいました。"}'::jsonb, '{"selected": "わかりにくかった"}'::jsonb, 'Bentuk biasa lampau kata sifat-I (わかりにくかった) langsung disambungkan dengan せいで.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1029d61f-f4db-539c-a5a6-dcb1e8c424a9'::uuid, 'e3241af6-4e4c-55e6-a158-8d993c07ff96'::uuid, NULL, 'reading', 'fill_blank', 'Pilih penghubung sebab yang sesuai nuansa kalimat: 大雨の ___ 、運動会が中止になって残念です。', '{"options": ["せいで", "おかげで", "はずで", "うちに"], "translation": "Gara-gara hujan deras, festival olahraga dibatalkan dan itu sangat disayangkan.", "sentence_template": "大雨の [blank] 、運動会が中止になって残念です。"}'::jsonb, '{"selected": "せいで"}'::jsonb, 'Karena akibatnya negatif (dibatalkan dan disayangkan), wajib memakai せいで.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, 'bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, 'Bicara & Rakit Laporan Kendala', 'Bicara Kendala', 'n3-u4-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('993249b1-5b35-5c50-8c47-134440b292a6'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara kereta terlambat, saya terlambat masuk kerja."', '{"display_text": "電車が遅れたせいで、遅刻してしまいました。", "romaji": "Densha ga okureta sei de, chikoku shite shimaimashita.", "phonetic_breakdown": ["den-sha ga", "o-ku-re-ta", "se-i de", "chi-ko-ku", "shi-te", "shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "電車が遅れたせいで、遅刻してしまいました。"}'::jsonb, 'Catatan etika kantor: saat melapor ke atasan, gunakan 電車が遅れたため agar lebih objektif dan tidak terkesan menyalahkan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('970c21f0-6f58-57b9-85f1-971591069d21'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara kurang olahraga, berat badan saya naik."', '{"display_text": "運動不足のせいで、体重が増えました。", "romaji": "Undoubusoku no sei de, taijuu ga fuemashita.", "phonetic_breakdown": ["un-dou-bu-so-ku no", "se-i de", "ta-i-juu ga", "fu-e-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "運動不足のせいで、体重が増えました。"}'::jsonb, '運動不足 (undoubusoku) berarti kurang olahraga; 体重 (taijuu) berarti berat badan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0c467d46-9621-508d-a619-c7277a82332f'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mungkin karena lelah, saya langsung tertidur."', '{"display_text": "疲れていたせいか、すぐ眠ってしまいました。", "romaji": "Tsukarete ita sei ka, sugu nemutte shimaimashita.", "phonetic_breakdown": ["tsu-ka-re-te i-ta", "se-i ka", "su-gu", "ne-mut-te", "shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "疲れていたせいか、すぐ眠ってしまいました。"}'::jsonb, '～せいか memberi nuansa perkiraan penyebab yang lembut.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('866b2b70-b280-591f-a67f-bee2a9bf94e7'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara salah tekan tombol, datanya terhapus."', '{"tokens": ["データが", "押して", "消えました。", "ボタンを", "おかげで、", "押し間違えた", "せいで、"], "target_translation": "Gara-gara salah tekan tombol, datanya terhapus.", "romaji": "Botan o oshimachigaeta sei de, deeta ga kiemashita."}'::jsonb, '["ボタンを", "押し間違えた", "せいで、", "データが", "消えました。"]'::jsonb, '押し間違えた (salah tekan) + せいで + データが消えました (data hilang).', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('41ff70a0-76ad-5303-afe2-dbc5a9e83c14'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara suara bising, saya tidak bisa mendengar suaranya."', '{"tokens": ["せいで、", "聞こえませんでした。", "騒音な", "声が", "騒音の", "おかげで、"], "target_translation": "Gara-gara suara bising, saya tidak bisa mendengar suaranya.", "romaji": "Souon no sei de, koe ga kikoemasen deshita."}'::jsonb, '["騒音の", "せいで、", "声が", "聞こえませんでした。"]'::jsonb, '騒音のせいで (gara-gara kebisingan) diikuti hasil negatif 聞こえませんでした.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('eaef1d10-cf71-54bb-af6f-398768f24088'::uuid, '8de66d94-d11d-5330-b89e-991feafa15bd'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara lupa membawa payung, baju saya basah."', '{"tokens": ["服が", "忘れて", "おかげで、", "忘れた", "せいで、", "濡れました。", "傘を"], "target_translation": "Gara-gara lupa membawa payung, baju saya basah.", "romaji": "Kasa o wasureta sei de, fuku ga nuremashita."}'::jsonb, '["傘を", "忘れた", "せいで、", "服が", "濡れました。"]'::jsonb, '忘れた (bentuk biasa lampau) + せいで.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, 'bccb108f-4ae1-5f87-a772-3a558268f645'::uuid, 'Evaluasi Unit 4: Kendala & Penyebab', 'Tes Unit 4', 'n3-u4-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('50c0b274-10d1-5fe1-837b-d5402700f3f7'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 急いで ___ せいで、大切な書類を家に忘れてしまいました。', '{"options": ["出た", "出て", "出ます", "出よう"], "translation": "Gara-gara berangkat terburu-buru, saya kelupaan dokumen penting di rumah.", "sentence_template": "急いで [blank] せいで、大切な書類を家に忘れてしまいました。"}'::jsonb, '{"selected": "出た"}'::jsonb, 'Bentuk biasa lampau 出た + せいで.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('beb8bffc-0333-5c2d-b451-01f00f7c92ad'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi dengan adjektiva-NA: 道が ___ せいで、目的地に着くまで時間がかかりました。', '{"options": ["複雑な", "複雑の", "複雑だ", "複雑で"], "translation": "Gara-gara jalannya rumit, butuh waktu lama untuk sampai ke tujuan.", "sentence_template": "道が [blank] せいで、目的地に着くまで時間がかかりました。"}'::jsonb, '{"selected": "複雑な"}'::jsonb, 'Kata sifat-NA memakai な sebelum せいで (複雑なせいで).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7507e08d-7609-5549-a921-4064116335e0'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'listening', 'listening_choice', 'Apa penyebab penjualan toko menurun minggu ini?', '{"audio_text": "一週間ずっと雨が降り続いたせいで、今週は来店客が大きく減りました。", "options": [{"id": "opt_1", "text": "Karena toko sedang melakukan renovasi"}, {"id": "opt_2", "text": "Karena produk baru belum tiba dari pabrik"}, {"id": "opt_3", "text": "Karena hujan turun terus-menerus selama seminggu"}, {"id": "opt_4", "text": "Karena banyak pegawai sedang cuti tahunan"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '一週間ずっと雨が降り続いたせいで berarti gara-gara hujan turun terus-menerus seminggu.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('94962e7f-517b-547d-8210-f079f72b7215'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa fokus bekerja siang ini?', '{"audio_text": "風邪薬を飲んだせいか、午後から急に強い眠気が出てきました。", "options": [{"id": "opt_1", "text": "Karena ruang kerjanya terlalu dingin"}, {"id": "opt_2", "text": "Karena ia belum sempat makan siang"}, {"id": "opt_3", "text": "Karena komputernya berjalan sangat lambat"}, {"id": "opt_4", "text": "Karena rasa kantuk kuat yang mungkin akibat minum obat flu"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '風邪薬を飲んだせいか、強い眠気が出てきました berarti muncul rasa kantuk kuat yang mungkin karena obat flu.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e100505f-8646-555d-bd63-bfb274ab4cc6'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara salah lihat jam, saya ketinggalan kereta terakhir."', '{"tokens": ["時間を", "せいで、", "終電に", "見間違えて", "乗り遅れました。", "おかげで、", "見間違えた"], "target_translation": "Gara-gara salah lihat jam, saya ketinggalan kereta terakhir.", "romaji": "Jikan o mimachigaeta sei de, shuuden ni noriokuremashita."}'::jsonb, '["時間を", "見間違えた", "せいで、", "終電に", "乗り遅れました。"]'::jsonb, '終電に乗り遅れる berarti ketinggalan kereta terakhir.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4a348cde-4cb5-5477-89b1-b440fc4f0b0c'::uuid, '5d57954e-ba71-59ea-99c5-be51c3364adc'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-004' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara topan, semua penerbangan dibatalkan."', '{"display_text": "台風のせいで、すべての便が欠航になりました。", "romaji": "Taifuu no sei de, subete no bin ga kekkou ni narimashita.", "phonetic_breakdown": ["ta-i-fuu no", "se-i de", "su-be-te no bin ga", "kek-kou ni", "na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "台風のせいで、すべての便が欠航になりました。"}'::jsonb, '便 (bin) berarti jadwal penerbangan. Kalimat ini sering terdengar di pengumuman bandara Jepang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, v_level_id, 'Sikap & Perbandingan (～に対して)', 'Gunakan ～に対して untuk menunjukkan sasaran sikap dalam layanan pelanggan, tanggapan terhadap usulan, dan perbandingan dua hal.', 'curriculum', 5);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, '0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, 'Kosakata Layanan Pelanggan & Sikap', 'Kosakata Layanan', 'n3-u5-kosakata', 'scales', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('41fc2c54-4933-5df5-9ce2-afd268b04016'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat layanan: お客様からの問い合わせに迅速に ___ します。', '{"options": ["対応", "注文", "配達", "見学"], "translation": "Saya menanggapi pertanyaan dari pelanggan dengan cepat.", "sentence_template": "お客様からの問い合わせに迅速に [blank] します。"}'::jsonb, '{"selected": "対応"}'::jsonb, '対応する (taiou suru) berarti menangani atau merespons pertanyaan/keluhan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('936bf770-5f52-5ea1-b1a7-cb35dea6057b'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk sikap kerja: 誰にでも丁寧な ___ で接することが大切です。', '{"options": ["態度", "温度", "速度", "角度"], "translation": "Penting untuk berinteraksi dengan sikap yang sopan kepada siapa pun.", "sentence_template": "誰にでも丁寧な [blank] で接することが大切です。"}'::jsonb, '{"selected": "態度"}'::jsonb, '態度 (taido) berarti sikap atau perilaku.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e6d74919-6d9d-548d-a782-7feedacc515f'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat rapat: 新しい企画について、社員から多くの ___ が寄せられました。', '{"options": ["意見", "天気", "住所", "費用"], "translation": "Terkait rencana baru, banyak pendapat masuk dari para karyawan.", "sentence_template": "新しい企画について、社員から多くの [blank] が寄せられました。"}'::jsonb, '{"selected": "意見"}'::jsonb, '意見 (iken) berarti pendapat atau masukan.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e93fb1d0-f790-55fd-be36-763cb0a90f7e'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk perbandingan data: 去年と今年の売上を ___ してみましょう。', '{"options": ["比較", "説明", "招待", "翻訳"], "translation": "Mari kita coba membandingkan penjualan tahun lalu dan tahun ini.", "sentence_template": "去年と今年の売上を [blank] してみましょう。"}'::jsonb, '{"selected": "比較"}'::jsonb, '比較する (hikaku suru) berarti membandingkan.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('55d930ae-33ca-503e-964c-0e5804eae617'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang sangat ditekankan oleh manajer toko dalam audio ini?', '{"audio_text": "初めて来店されたお客様にも、わかりやすく笑顔でご案内するよう心がけてください。", "options": [{"id": "opt_1", "text": "Memberi panduan dengan jelas dan tersenyum kepada pelanggan baru"}, {"id": "opt_2", "text": "Menawarkan kartu keanggotaan kepada setiap pengunjung"}, {"id": "opt_3", "text": "Memastikan kasir tidak pernah antre lebih dari tiga menit"}, {"id": "opt_4", "text": "Menjaga kebersihan area parkir sebelum toko buka"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'わかりやすく笑顔でご案内する berarti memandu dengan jelas dan senyuman.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('01e5bf4e-2299-56ff-8f50-82ed2ab635ee'::uuid, 'acc54292-6ef6-588a-9e13-4074cfb3d5fa'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana hasil survei kepuasan pelanggan bulan ini?', '{"audio_text": "商品の品質には満足という声が多い一方で、配送のスピードについては改善を求める意見がありました。", "options": [{"id": "opt_1", "text": "Pelanggan mengeluhkan harga produk yang terlalu tinggi"}, {"id": "opt_2", "text": "Kualitas produk memuaskan, tetapi kecepatan pengiriman diminta diperbaiki"}, {"id": "opt_3", "text": "Sebagian besar pelanggan puas dengan kecepatan pengiriman"}, {"id": "opt_4", "text": "Survei bulan ini belum selesai direkapitulasi"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '品質には満足 (puas dengan kualitas) dan 配送のスピードについては改善を求める (meminta perbaikan kecepatan pengiriman).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, '0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, 'Pola ～に対して & ～に対する', 'Pola Ni Taishite', 'n3-u5-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ea84ed92-3005-5b85-9ab7-c5a15eea5f89'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi sasaran sikap: 目上の人 ___ 敬語を使うのがマナーです。', '{"options": ["に対して", "について", "にとって", "によって"], "translation": "Menggunakan bahasa hormat kepada orang yang lebih senior adalah etika.", "sentence_template": "目上の人 [blank] 敬語を使うのがマナーです。"}'::jsonb, '{"selected": "に対して"}'::jsonb, 'Nomina + に対して menunjukkan sasaran sikap atau tindakan (kepada/terhadap).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0fe354aa-f289-573d-a4c2-1e5c7e6bdd67'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang menerangkan nomina: 環境問題 ___ 関心が年々高まっています。', '{"options": ["に対する", "に対して", "に対した", "に対します"], "translation": "Perhatian terhadap masalah lingkungan meningkat dari tahun ke tahun.", "sentence_template": "環境問題 [blank] 関心が年々高まっています。"}'::jsonb, '{"selected": "に対する"}'::jsonb, 'Jika langsung menerangkan kata benda (関心 = perhatian), に対して berubah menjadi に対する.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8a1e5640-872c-5940-88c6-1ac446d0850e'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat perbandingan: 兄が社交的なの ___ 、弟は物静かです。', '{"options": ["に対して", "のおかげで", "のせいで", "のはずで"], "translation": "Berbeda dengan kakak yang supel, adik pendiam.", "sentence_template": "兄が社交的なの [blank] 、弟は物静かです。"}'::jsonb, '{"selected": "に対して"}'::jsonb, '[Bentuk Biasa] + のに対して digunakan untuk membandingkan dua hal yang kontras.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('b18f5496-93ee-576e-bda2-670bab2e598f'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya menggunakan bahasa yang sopan terhadap pelanggan."', '{"tokens": ["丁寧な言葉を", "お客様に", "よって", "対して", "対する", "使います。"], "target_translation": "Saya menggunakan bahasa yang sopan terhadap pelanggan.", "romaji": "Okyakusama ni taishite teineina kotoba o tsukaimasu."}'::jsonb, '["お客様に", "対して", "丁寧な言葉を", "使います。"]'::jsonb, 'お客様に対して (terhadap pelanggan) + 丁寧な言葉を使います.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('28d39099-b5fa-539a-80f4-7f8259ab3545'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya menjawab pertanyaan terhadap usulan ini."', '{"tokens": ["この提案に", "ついて", "答えます。", "質問に", "対して", "対する"], "target_translation": "Saya menjawab pertanyaan terhadap usulan ini.", "romaji": "Kono teian ni taisuru shitsumon ni kotaemasu."}'::jsonb, '["この提案に", "対する", "質問に", "答えます。"]'::jsonb, 'Karena langsung menerangkan nomina 質問, gunakan に対する.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('408b46ca-1f43-5566-9e1d-327bd228c752'::uuid, 'f6c46fa5-e309-5a50-bd6e-0950353ee258'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'listening', 'listening_choice', 'Apa perbandingan yang dijelaskan pembicara tentang dua wilayah tersebut?', '{"audio_text": "都心は交通が便利なに対して、郊外は家賃が安くて自然が豊かです。", "options": [{"id": "opt_1", "text": "Pusat kota lebih murah sewanya daripada pinggiran kota"}, {"id": "opt_2", "text": "Pinggiran kota lebih ramai dan praktis transportasinya"}, {"id": "opt_3", "text": "Pusat kota praktis transportasinya, sedangkan pinggiran kota murah sewanya dan asri"}, {"id": "opt_4", "text": "Kedua wilayah memiliki biaya hidup yang hampir sama"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, 'Pembicara mengontraskan 都心 (pusat kota: transportasi praktis) dengan 郊外 (pinggiran: sewa murah dan kaya alam).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, '0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, 'Simak & Baca: Perbandingan & Tanggapan', 'Simak Perbandingan', 'n3-u5-dengar-baca', 'compass', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8ce4c5a9-a599-5aa0-8842-39306e03500b'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana sikap atasan terhadap kesalahan pegawai baru?', '{"audio_text": "部長は新人のミスに対して厳しく叱るのではなく、原因を一緒に考えてくれます。", "options": [{"id": "opt_1", "text": "Memarahi pegawai baru di depan seluruh tim"}, {"id": "opt_2", "text": "Langsung memindahkan tugas ke pegawai lain"}, {"id": "opt_3", "text": "Meminta laporan tertulis sepanjang lima halaman"}, {"id": "opt_4", "text": "Tidak memarahi dengan keras, melainkan memikirkan penyebabnya bersama"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '厳しく叱るのではなく、原因を一緒に考えてくれます berarti tidak memarahi keras, tetapi memikirkan penyebabnya bersama.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a0789019-ca88-53d3-850b-bc207cdb58fd'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'listening', 'listening_choice', 'Apa perbedaan cara kerja dua tim dalam audio ini?', '{"audio_text": "営業部は外出が多いのに対して、開発部はほとんど社内でパソコン作業をしています。", "options": [{"id": "opt_1", "text": "Tim penjualan banyak keluar kantor, sedangkan tim pengembang bekerja di kantor"}, {"id": "opt_2", "text": "Tim pengembang lebih sering dinas ke luar kota"}, {"id": "opt_3", "text": "Kedua tim sama-sama bekerja dari rumah setiap hari"}, {"id": "opt_4", "text": "Tim penjualan jarang menggunakan komputer"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '営業部は外出が多い (banyak keluar) dikontraskan dengan 開発部はほとんど社内で作業 (hampir selalu kerja di kantor).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bba387e8-5481-529d-9b44-48bf18340ff5'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang dibahas terkait keluhan pelanggan?', '{"audio_text": "お客様からのご意見に対して、社内で改善策を話し合う予定です。", "options": [{"id": "opt_1", "text": "Perusahaan memutuskan mengabaikan keluhan kecil"}, {"id": "opt_2", "text": "Perusahaan berencana membahas langkah perbaikan secara internal"}, {"id": "opt_3", "text": "Pelanggan akan diberikan kupon belanja gratis"}, {"id": "opt_4", "text": "Layanan pelanggan akan dialihkan ke pihak luar"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '社内で改善策を話し合う予定です berarti berencana mendiskusikan langkah perbaikan di internal.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('eb6d514c-25de-5e30-9011-8abc4c8a3360'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 彼の意見 ___ 反対する人はいませんでした。', '{"options": ["に対して", "に対する", "において", "にとって"], "translation": "Tidak ada seorang pun yang menentang pendapatnya.", "sentence_template": "彼の意見 [blank] 反対する人はいませんでした。"}'::jsonb, '{"selected": "に対して"}'::jsonb, '意見に対して反対する berarti menentang (terhadap) pendapat.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c9720f53-f7a2-55b7-98b2-035797668789'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi frasa nomina: 日本の文化 ___ 理解を深めたいです。', '{"options": ["に対する", "に対して", "にとって", "について"], "translation": "Saya ingin memperdalam pemahaman terhadap budaya Jepang.", "sentence_template": "日本の文化 [blank] 理解を深めたいです。"}'::jsonb, '{"selected": "に対する"}'::jsonb, 'Sebelum kata benda 理解 (pemahaman), gunakan に対する.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('9e4b5335-46b1-5871-819b-b2065dad62c9'::uuid, '33bf8196-60e5-5a29-abc3-7659791536fd'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kontras musim: 日本の夏が蒸し暑いの ___ 、冬は乾燥しています。', '{"options": ["に対して", "おかげで", "せいで", "うちに"], "translation": "Berbeda dengan musim panas Jepang yang lembap panas, musim dinginnya kering.", "sentence_template": "日本の夏が蒸し暑いの [blank] 、冬は乾燥しています。"}'::jsonb, '{"selected": "に対して"}'::jsonb, 'のに対して menghubungkan dua sifat musim yang berlawanan.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, '0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, 'Bicara & Rakit Sikap Profesional', 'Bicara Profesional', 'n3-u5-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a59d99e2-4547-5fe7-a4d1-82e7003ffa95'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas dukungan Anda terhadap proyek kami."', '{"display_text": "弊社の企画に対するご支援、ありがとうございます。", "romaji": "Heisha no kikaku ni taisuru goshien, arigatou gozaimasu.", "phonetic_breakdown": ["he-i-sha no", "ki-ka-ku ni", "ta-i-su-ru", "go-shi-en", "a-ri-ga-tou", "go-za-i-ma-su"]}'::jsonb, '{"expected_transcript": "弊社の企画に対するご支援、ありがとうございます。"}'::jsonb, '弊社 (heisha) adalah sebutan rendah hati untuk perusahaan sendiri dalam bisnis Jepang.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5b1fbf6e-5286-5998-9e88-85ee560acd5d'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berbeda dengan kota yang ramai, desa itu tenang."', '{"display_text": "都会がにぎやかなのに対して、その村は静かです。", "romaji": "Tokai ga nigiyakana no ni taishite, sono mura wa shizuka desu.", "phonetic_breakdown": ["to-ka-i ga", "ni-gi-ya-ka-na no ni", "ta-i-shi-te", "so-no mu-ra wa", "shi-zu-ka de-su"]}'::jsonb, '{"expected_transcript": "都会がにぎやかなのに対して、その村は静かです。"}'::jsonb, 'Perhatikan adjektiva-NA にぎやか memakai な sebelum のに対して.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7a7b18fc-8453-511e-bbef-f6af126af708'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bertanggung jawab terhadap pekerjaan saya."', '{"display_text": "自分の仕事に対して責任を持っています。", "romaji": "Jibun no shigoto ni taishite sekinin o motte imasu.", "phonetic_breakdown": ["ji-bun no", "shi-go-to ni", "ta-i-shi-te", "se-ki-nin o", "mot-te i-ma-su"]}'::jsonb, '{"expected_transcript": "自分の仕事に対して責任を持っています。"}'::jsonb, '責任を持つ (sekinin o motsu) berarti memiliki rasa tanggung jawab.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('06781cd1-877a-59e9-b86b-df9a08818bcc'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Beliau selalu bersikap ramah kepada siapa pun."', '{"tokens": ["対する", "親切です。", "よって", "対しても", "誰に", "あの人は"], "target_translation": "Beliau selalu bersikap ramah kepada siapa pun.", "romaji": "Ano hito wa dare ni taishite mo shinsetsu desu."}'::jsonb, '["あの人は", "誰に", "対しても", "親切です。"]'::jsonb, '誰に対しても berarti ''terhadap siapa pun''.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('00628a27-4d4a-507d-915a-4a45de56f201'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Berbeda dengan tahun lalu yang sedikit hujan, tahun ini banyak hujan."', '{"tokens": ["去年は", "今年は", "対して、", "多いです。", "少なくて", "おかげで、", "雨が少なかったのに"], "target_translation": "Berbeda dengan tahun lalu yang sedikit hujan, tahun ini banyak hujan.", "romaji": "Kyonen wa ame ga sukunakatta no ni taishite, kotoshi wa ooi desu."}'::jsonb, '["去年は", "雨が少なかったのに", "対して、", "今年は", "多いです。"]'::jsonb, '少なかったのに + 対して mengontraskan kondisi curah hujan dua tahun.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ce226a32-2a09-51c8-bf30-c44a3de5e5c8'::uuid, '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya memiliki minat terhadap teknologi terbaru."', '{"tokens": ["興味が", "対して", "最新の技術に", "対する", "あります。", "せいで"], "target_translation": "Saya memiliki minat terhadap teknologi terbaru.", "romaji": "Saishin no gijutsu ni taisuru kyoumi ga arimasu."}'::jsonb, '["最新の技術に", "対する", "興味が", "あります。"]'::jsonb, 'Karena menerangkan nomina 興味 (minat), gunakan に対する.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, '0b09459e-73c2-57b2-b6e7-990e696dc333'::uuid, 'Evaluasi Unit 5: Sikap & Perbandingan', 'Tes Unit 5', 'n3-u5-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('124af529-e683-5626-9ad6-929875865f68'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang benar: 新製品 ___ アンケート調査を実施しました。', '{"options": ["に対する", "に対して", "に対した", "に対します"], "translation": "Kami telah melaksanakan survei kuesioner terhadap produk baru.", "sentence_template": "新製品 [blank] アンケート調査を実施しました。"}'::jsonb, '{"selected": "に対する"}'::jsonb, 'アンケート調査 adalah nomina, sehingga bentuk penghubung yang tepat adalah に対する.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bd1632cb-f043-552b-8c81-9868d280930f'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kontras kebiasaan: 姉は朝型なの ___ 、私は夜型です。', '{"options": ["に対して", "のために", "のおかげで", "のせいで"], "translation": "Berbeda dengan kakak perempuan yang tipe pagi, saya tipe malam.", "sentence_template": "姉は朝型なの [blank] 、私は夜型です。"}'::jsonb, '{"selected": "に対して"}'::jsonb, 'Nomina 朝型 + なのに対して mengontraskan dua tipe kebiasaan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('400ce88f-bae4-594c-b514-f27d277e02ce'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'listening', 'listening_choice', 'Bagaimana perbandingan peserta seminar tahun ini dan tahun lalu?', '{"audio_text": "去年の参加者が五十人だったのに対して、今年は百人以上が集まりました。", "options": [{"id": "opt_1", "text": "Tahun ini peserta berkurang separuh"}, {"id": "opt_2", "text": "Jumlah peserta tahun lalu dan tahun ini sama persis"}, {"id": "opt_3", "text": "Tahun lalu lima puluh orang, sedangkan tahun ini lebih dari seratus orang"}, {"id": "opt_4", "text": "Seminar tahun lalu dibatalkan karena kurang peserta"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '去年の参加者が五十人だったのに対して、今年は百人以上 berarti 50 orang tahun lalu berbanding lebih dari 100 orang tahun ini.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e7434c68-f69b-5cf1-b9c1-1c41f147ef21'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'listening', 'listening_choice', 'Apa yang ditekankan perusahaan dalam menanggapi masukan karyawan?', '{"audio_text": "社員からの提案に対して、必ず一週間以内に回答するルールになっています。", "options": [{"id": "opt_1", "text": "Usulan hanya diterima saat rapat tahunan"}, {"id": "opt_2", "text": "Karyawan tidak boleh mengirim usulan secara anonim"}, {"id": "opt_3", "text": "Semua usulan otomatis disetujui oleh manajer"}, {"id": "opt_4", "text": "Setiap usulan wajib dijawab maksimal dalam satu minggu"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '必ず一週間以内に回答するルール berarti aturan wajib menjawab dalam waktu satu minggu.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8f122304-c01e-5ded-a9fe-2b9abf62a6d3'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya sangat berterima kasih atas perhatian Anda terhadap keluarga saya."', '{"tokens": ["対して", "家族に", "対する", "感謝しています。", "せいで", "ご配慮に"], "target_translation": "Saya sangat berterima kasih atas perhatian Anda terhadap keluarga saya.", "romaji": "Kazoku ni taisuru gohairyo ni kansha shite imasu."}'::jsonb, '["家族に", "対する", "ご配慮に", "感謝しています。"]'::jsonb, 'ご配慮 (perhatian/kepedulian) adalah nomina sehingga memakai に対する.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('23b2bff4-a1a2-5eb6-ad44-c762700e48d9'::uuid, '916df766-6712-52e0-a1ac-72f2a24b3dee'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-005' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menjawab setiap pertanyaan pelanggan dengan tulus."', '{"display_text": "お客様のご質問に対して誠実にお答えします。", "romaji": "Okyakusama no goshitsumon ni taishite seijitsu ni okotae shimasu.", "phonetic_breakdown": ["o-kya-ku-sa-ma no", "go-shi-tsu-mon ni", "ta-i-shi-te", "se-i-ji-tsu ni", "o-ko-ta-e shi-ma-su"]}'::jsonb, '{"expected_transcript": "お客様のご質問に対して誠実にお答えします。"}'::jsonb, '誠実に (seijitsu ni) berarti dengan tulus/jujur. Kalimat formal yang kuat untuk layanan pelanggan.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, v_level_id, 'Mumpung & Selagi (～うちに)', 'Manfaatkan pola ～うちに untuk menyatakan kesempatan yang perlu diambil sebelum kondisi berubah serta perubahan yang terjadi tanpa disadari.', 'curriculum', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, '3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, 'Kosakata Waktu, Kesempatan & Perubahan', 'Kosakata Waktu', 'n3-u6-kosakata', 'clock', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fb5aabfa-c33e-5391-84cd-717131187e67'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat manajemen waktu: 提出の ___ を守って書類を出しましょう。', '{"options": ["締め切り", "始まり", "見送り", "割り引き"], "translation": "Mari kumpulkan dokumen dengan mematuhi batas waktu pengumpulan.", "sentence_template": "提出の [blank] を守って書類を出しましょう。"}'::jsonb, '{"selected": "締め切り"}'::jsonb, '締め切り (shimekiri) berarti tenggat atau batas waktu pengumpulan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5a351886-9705-5703-9142-230ca459d8bb'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk kesempatan: せっかくの ___ ですから、ぜひ参加してください。', '{"options": ["機会", "機械", "器械", "境界"], "translation": "Karena ini kesempatan berharga, silakan ikut berpartisipasi.", "sentence_template": "せっかくの [blank] ですから、ぜひ参加してください。"}'::jsonb, '{"selected": "機会"}'::jsonb, '機会 (kikai) berarti kesempatan/peluang. 機械 berarti mesin.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('80dcfc75-4d91-53a2-9544-16bc15f5cad1'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang cuaca sore: 夕方になると急に空が ___ なります。', '{"options": ["暗く", "軽く", "丸く", "細く"], "translation": "Saat menjelang sore, langit tiba-tiba menjadi gelap.", "sentence_template": "夕方になると急に空が [blank] なります。"}'::jsonb, '{"selected": "暗く"}'::jsonb, '暗くなる (kuraku naru) berarti menjadi gelap.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0e06e6bf-865a-548d-b61e-258b74f85f2d'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk ingatan: 授業の内容は ___ が新しいうちにまとめます。', '{"options": ["記憶", "記録", "記念", "気温"], "translation": "Isi pelajaran saya rangkum selagi ingatan masih segar.", "sentence_template": "授業の内容は [blank] が新しいうちにまとめます。"}'::jsonb, '{"selected": "記憶"}'::jsonb, '記憶が新しい (kioku ga atarashii) berarti ingatan masih segar.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('061fe02c-bc23-51ce-ae58-daff7b9343cf'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'listening', 'listening_choice', 'Kapan pembicara menyarankan untuk pergi ke supermarket?', '{"audio_text": "夕方はレジがすごく混むので、空いている昼間のうちに買い物を済ませたほうがいいですよ。", "options": [{"id": "opt_1", "text": "Siang hari selagi masih sepi"}, {"id": "opt_2", "text": "Sore hari saat diskon makanan dimulai"}, {"id": "opt_3", "text": "Malam hari sebelum toko tutup"}, {"id": "opt_4", "text": "Pagi-pagi sekali sebelum berangkat kerja"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '空いている昼間のうちに berarti pada siang hari selagi sepi.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('33e23d7c-ede4-52b4-b44e-13936bc52a60'::uuid, '63ae0fc4-822c-5680-b9b6-2019a60e3d3e'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara ingin bepergian keliling Jepang tahun ini?', '{"audio_text": "日本に住んでいる間に、できるだけ多くの地方を訪れておきたいと思っています。", "options": [{"id": "opt_1", "text": "Karena tiket kereta sedang gratis bulan ini"}, {"id": "opt_2", "text": "Karena ingin mengunjungi banyak daerah selama masih tinggal di Jepang"}, {"id": "opt_3", "text": "Karena mendapat tugas dinas ke seluruh prefektur"}, {"id": "opt_4", "text": "Karena orang tuanya akan datang berkunjung minggu depan"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '日本に住んでいる間に、できるだけ多くの地方を訪れておきたい berarti ingin mengunjungi banyak daerah selama tinggal di Jepang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, '3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, 'Pola ～うちに (Mumpung & Tanpa Disadari)', 'Pola Uchi ni', 'n3-u6-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('202bfab7-5b8f-5a91-8572-8fd070bca432'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat ajakan makan: スープが ___ うちに召し上がってください。', '{"options": ["温かい", "温かいな", "温かいの", "温かくて"], "translation": "Silakan dinikmati selagi supnya masih hangat.", "sentence_template": "スープが [blank] うちに召し上がってください。"}'::jsonb, '{"selected": "温かい"}'::jsonb, 'Kata sifat-I langsung diikuti うちに (温かいうちに).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c8e8bd86-69f4-56db-a9a3-2023faa54e3b'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk negatif sebelum berubah kondisi: 雨が ___ うちに家へ帰りましょう。', '{"options": ["降らない", "降る", "降った", "降って"], "translation": "Mari pulang ke rumah selagi belum turun hujan.", "sentence_template": "雨が [blank] うちに家へ帰りましょう。"}'::jsonb, '{"selected": "降らない"}'::jsonb, 'Bentuk-NAI + うちに (降らないうちに) berarti ''selagi belum / sebelum terjadi''.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8305cbde-b954-5bea-a639-d5e9498b1da1'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 独身 ___ うちにいろいろな国を旅したいです。', '{"options": ["の", "な", "に", "で"], "translation": "Selagi masih lajang, saya ingin bepergian ke berbagai negara.", "sentence_template": "独身 [blank] うちにいろいろな国を旅したいです。"}'::jsonb, '{"selected": "の"}'::jsonb, 'Nomina + の + うちに (独身のうちに).', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4ce3578c-cfe8-57ee-aa32-5f0743f0e584'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Mari mencatat selagi belum lupa."', '{"tokens": ["忘れない", "うちに", "メモを", "せいで", "とりましょう。", "忘れる"], "target_translation": "Mari mencatat selagi belum lupa.", "romaji": "Wasurenai uchi ni memo o torimashou."}'::jsonb, '["忘れない", "うちに", "メモを", "とりましょう。"]'::jsonb, '忘れないうちに berarti ''mumpung belum lupa''.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c51115df-2973-5c6e-b30e-4bbbab21995b'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Selagi muda, sebaiknya mencoba banyak hal."', '{"tokens": ["ほうがいいです。", "挑戦した", "挑戦する", "いろいろなことに", "若いの", "うちに", "若い"], "target_translation": "Selagi muda, sebaiknya mencoba banyak hal.", "romaji": "Wakai uchi ni iroirona koto ni chousen shita hou ga ii desu."}'::jsonb, '["若い", "うちに", "いろいろなことに", "挑戦した", "ほうがいいです。"]'::jsonb, 'Kata sifat-I 若い + うちに + ～たほうがいいです (sebaiknya).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bcd4bf62-45e4-5f39-84ce-f81a177bfb24'::uuid, '90ec6cc0-3dff-5412-b034-3b6ec1707057'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'listening', 'listening_choice', 'Perubahan apa yang terjadi tanpa disadari oleh pembicara?', '{"audio_text": "日本のドラマを毎日見ているうちに、自然な会話表現がわかるようになりました。", "options": [{"id": "opt_1", "text": "Ia menjadi sering tidur terlalu malam"}, {"id": "opt_2", "text": "Ia mulai bosan menonton acara televisi"}, {"id": "opt_3", "text": "Ia menjadi mengerti ungkapan percakapan alami"}, {"id": "opt_4", "text": "Ia memutuskan pindah bekerja di stasiun televisi"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '～ているうちに menunjukkan perubahan bertahap yang terjadi selama melakukan sesuatu secara terus-menerus.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, '3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, 'Simak & Baca: Memanfaatkan Momen', 'Simak Momen', 'n3-u6-dengar-baca', 'lightbulb', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7acaf7f4-8499-5f80-9ff0-43bab6e68e7a'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara langsung mencuci piring setelah makan?', '{"audio_text": "油汚れは時間が経つと落ちにくくなるので、冷めないうちに洗ってしまいます。", "options": [{"id": "opt_1", "text": "Karena air panas di dapurnya sering mati malam hari"}, {"id": "opt_2", "text": "Karena ia ingin segera keluar rumah bertemu teman"}, {"id": "opt_3", "text": "Karena wastafel dapurnya sangat sempit"}, {"id": "opt_4", "text": "Karena noda minyak sulit hilang jika dibiarkan lama, jadi dicuci selagi belum dingin"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '冷めないうちに洗ってしまいます berarti langsung mencucinya selagi belum dingin.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('aa026d1e-5158-57b8-8bd5-13319c503357'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang terjadi saat pembicara membaca buku di kereta?', '{"audio_text": "電車で本を読んでいるうちに眠くなって、降りる駅を乗り過ごしてしまいました。", "options": [{"id": "opt_1", "text": "Ia mengantuk dan terlewat stasiun tujuannya"}, {"id": "opt_2", "text": "Ia berhasil menamatkan seluruh buku sebelum tiba"}, {"id": "opt_3", "text": "Ia kehilangan pembatas buku di kursi kereta"}, {"id": "opt_4", "text": "Ia bertemu teman lama dari kampus"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '降りる駅を乗り過ごしてしまいました berarti terlewat stasiun tempat turun.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6f468123-db58-5f54-903e-41d620899d45'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'listening', 'listening_choice', 'Saran apa yang diberikan pembicara tentang belajar di Jepang?', '{"audio_text": "日本にいるうちに、敬語やビジネスマナーをしっかり身につけておきたいですね。", "options": [{"id": "opt_1", "text": "Segera membuka rekening bank sebelum pulang"}, {"id": "opt_2", "text": "Menguasai bahasa hormat dan etika bisnis selagi berada di Jepang"}, {"id": "opt_3", "text": "Mencari pekerjaan paruh waktu di restoran"}, {"id": "opt_4", "text": "Membeli banyak buku kamus untuk dibawa pulang"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '日本にいるうちに...身につけておきたい berarti ingin menguasainya selagi berada di Jepang.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4cd5debd-abbb-58d8-ba45-9c2eeae09e4d'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi dengan adjektiva-NA: 仕事が ___ うちに、溜まっていた書類を片づけました。', '{"options": ["暇な", "暇の", "暇だ", "暇で"], "translation": "Selagi pekerjaan sedang senggang, saya membereskan dokumen yang menumpuk.", "sentence_template": "仕事が [blank] うちに、溜まっていた書類を片づけました。"}'::jsonb, '{"selected": "暇な"}'::jsonb, 'Kata sifat-NA 暇 memakai な sebelum うちに (暇なうちに).', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('84e776f1-57e6-5bde-b594-fa9f1af43d16'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk perubahan bertahap: 毎日練習 ___ うちに、だんだん弾けるようになりました。', '{"options": ["している", "した", "して", "します"], "translation": "Selagi terus berlatih setiap hari, lama-kelamaan saya menjadi bisa memainkannya.", "sentence_template": "毎日練習 [blank] うちに、だんだん弾けるようになりました。"}'::jsonb, '{"selected": "している"}'::jsonb, 'Verba ～ている + うちに menyatakan perubahan yang muncul secara alami saat proses berlangsung.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3249366a-8d3d-5392-8eb8-b4d324fe84ee'::uuid, 'eeaab0e0-7888-5746-a517-dea0ee01d15b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi ungkapan waktu: 明るい ___ 庭の掃除を終わらせましょう。', '{"options": ["うちに", "せいで", "おかげで", "はずで"], "translation": "Mari selesaikan bersih-bersih halaman selagi hari masih terang.", "sentence_template": "明るい [blank] 庭の掃除を終わらせましょう。"}'::jsonb, '{"selected": "うちに"}'::jsonb, '明るいうちに berarti selagi masih terang (sebelum gelap).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, '3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, 'Bicara & Rakit Kalimat Kesempatan', 'Bicara Kesempatan', 'n3-u6-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('eb564c6e-9f82-5e3d-b313-505a9676df54'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mari makan selagi masih hangat."', '{"display_text": "温かいうちに食べましょう。", "romaji": "Atatakai uchi ni tabemashou.", "phonetic_breakdown": ["a-ta-ta-ka-i", "u-chi ni", "ta-be-ma-shou"]}'::jsonb, '{"expected_transcript": "温かいうちに食べましょう。"}'::jsonb, 'Ungkapan sangat akrab dan alami saat mengajak makan hidangan yang baru disajikan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('caabf047-af98-5d5d-a3b9-49eea92046be'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya pulang selagi belum turun salju."', '{"display_text": "雪が降らないうちに帰ったほうがいいです。", "romaji": "Yuki ga furanai uchi ni kaetta hou ga ii desu.", "phonetic_breakdown": ["yu-ki ga", "fu-ra-na-i", "u-chi ni", "ka-et-ta", "hou ga i-i de-su"]}'::jsonb, '{"expected_transcript": "雪が降らないうちに帰ったほうがいいです。"}'::jsonb, '降らないうちに (selagi belum turun) sering dipasangkan dengan ～たほうがいいです.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c6dadc8a-1f11-5669-89d9-5793c322f3a2'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Selagi berbicara, rasa gugup saya menghilang."', '{"display_text": "話しているうちに緊張がほぐれました。", "romaji": "Hanashite iru uchi ni kinchou ga hoguremashita.", "phonetic_breakdown": ["ha-na-shi-te i-ru", "u-chi ni", "kin-chou ga", "ho-gu-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "話しているうちに緊張がほぐれました。"}'::jsonb, '緊張がほぐれる (kinchou ga hogureru) berarti ketegangan/rasa gugup mencair.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3919a681-aada-5fc0-9ed9-0980244f2fd6'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Mari memeriksa jadwal selagi ada waktu."', '{"tokens": ["せいで", "うちに", "時間があった", "スケジュールを", "時間がある", "確認しましょう。"], "target_translation": "Mari memeriksa jadwal selagi ada waktu.", "romaji": "Jikan ga aru uchi ni sukejuuru o kakunin shimashou."}'::jsonb, '["時間がある", "うちに", "スケジュールを", "確認しましょう。"]'::jsonb, '時間がある + うちに berarti mumpung ada waktu.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6f1d9fc9-b6fb-5794-8022-c28ccfd011ec'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Selagi anak-anak tidur, saya menyelesaikan pekerjaan rumah."', '{"tokens": ["うちに", "子どもが", "寝た", "ように", "寝ている", "終わらせます。", "家事を"], "target_translation": "Selagi anak-anak tidur, saya menyelesaikan pekerjaan rumah.", "romaji": "Kodomo ga nete iru uchi ni kaji o owarasemasu."}'::jsonb, '["子どもが", "寝ている", "うちに", "家事を", "終わらせます。"]'::jsonb, '寝ているうちに menyatakan tindakan yang diselesaikan sebelum anak terbangun.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('297b30ac-5603-5b20-aa47-a22925fdb1bd'::uuid, '24f08bc2-3479-57e6-a002-e5714e517ea7'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Selagi masih mahasiswa, saya ingin belajar banyak bahasa asing."', '{"tokens": ["たくさん", "学生な", "外国語を", "はずで", "学生の", "勉強したいです。", "うちに"], "target_translation": "Selagi masih mahasiswa, saya ingin belajar banyak bahasa asing.", "romaji": "Gakusei no uchi ni gaikokugo o takusan benkyou shitai desu."}'::jsonb, '["学生の", "うちに", "外国語を", "たくさん", "勉強したいです。"]'::jsonb, 'Nomina 学生 + の + うちに.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('d94d3333-e246-539d-8914-dde6a731d00f'::uuid, '3b8b30d9-1b7b-5afd-8805-cb7871188df5'::uuid, 'Evaluasi Unit 6: Manajemen Waktu', 'Tes Unit 6', 'n3-u6-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a96ddeb3-502b-5e6c-bd72-b54ca2f05e28'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang tepat: セールが ___ うちに、冬用のコートを買っておきたいです。', '{"options": ["終わらない", "終わる", "終わった", "終わって"], "translation": "Selagi diskon belum berakhir, saya ingin membeli mantel musim dingin.", "sentence_template": "セールが [blank] うちに、冬用のコートを買っておきたいです。"}'::jsonb, '{"selected": "終わらない"}'::jsonb, '終わらないうちに berarti ''selagi belum berakhir / sebelum selesai''.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a0d973d4-270a-5408-9fd0-80a5664cccf4'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi perubahan alami: 日本で暮らしている ___ 、日本の四季が大好きになりました。', '{"options": ["うちに", "せいで", "に対して", "はずだ"], "translation": "Selama tinggal di Jepang, lama-kelamaan saya menjadi sangat menyukai empat musim Jepang.", "sentence_template": "日本で暮らしている [blank] 、日本の四季が大好きになりました。"}'::jsonb, '{"selected": "うちに"}'::jsonb, '暮らしているうちに mengekspresikan perubahan perasaan yang terjadi secara bertahap.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('cb668f3b-fde0-5823-a57d-c48ae799b5be'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'listening', 'listening_choice', 'Kapan pembicara berencana mendaftar ujian JLPT?', '{"audio_text": "人気のある会場はすぐ満席になるので、受付が始まったら早いうちに申し込むつもりです。", "options": [{"id": "opt_1", "text": "Sehari sebelum pendaftaran resmi ditutup"}, {"id": "opt_2", "text": "Setelah menanyakan lokasi ujian kepada teman"}, {"id": "opt_3", "text": "Segera pada tahap awal begitu pendaftaran dibuka"}, {"id": "opt_4", "text": "Pada bulan depan setelah gaji turun"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '早いうちに申し込むつもりです berarti berencana mendaftar selagi masih awal.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6de2ff59-2246-5075-afb1-62b895809ef7'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'listening', 'listening_choice', 'Apa yang terjadi saat pembicara mendengarkan musik santai?', '{"audio_text": "静かな音楽を聴いているうちに、いつの間にかソファで寝てしまいました。", "options": [{"id": "opt_1", "text": "Ia berhasil menyelesaikan seluruh laporan kerjanya"}, {"id": "opt_2", "text": "Ia menjadi terinspirasi menulis lagu sendiri"}, {"id": "opt_3", "text": "Ia menyadari baterainya hampir habis"}, {"id": "opt_4", "text": "Tanpa sadar ia tertidur di sofa"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, 'いつの間にかソファで寝てしまいました berarti tanpa sadar tertidur di sofa.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3381c64b-36e9-534e-b830-0264c997a355'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Mari memotret selagi bunga sakura masih mekar."', '{"tokens": ["撮りましょう。", "咲いた", "桜が", "うちに", "咲いている", "写真を", "せいで"], "target_translation": "Mari memotret selagi bunga sakura masih mekar.", "romaji": "Sakura ga saite iru uchi ni shashin o torimashou."}'::jsonb, '["桜が", "咲いている", "うちに", "写真を", "撮りましょう。"]'::jsonb, '咲いているうちに berarti selagi masih mekar (sebelum gugur).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6db916c0-ee80-5efd-a915-91e76a8d62ae'::uuid, 'd94d3333-e246-539d-8914-dde6a731d00f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-006' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mari kita konfirmasi detailnya selagi ingatan masih segar."', '{"display_text": "記憶が新しいうちに詳細を確認しましょう。", "romaji": "Kioku ga atarashii uchi ni shousai o kakunin shimashou.", "phonetic_breakdown": ["ki-o-ku ga", "a-ta-ra-shi-i", "u-chi ni", "shou-sa-i o", "ka-ku-nin", "shi-ma-shou"]}'::jsonb, '{"expected_transcript": "記憶が新しいうちに詳細を確認しましょう。"}'::jsonb, '詳細 (shousai) berarti rincian/detail. Sangat cocok dipakai tepat seusai rapat.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, v_level_id, 'Dugaan Logis (～はずだ)', 'Gunakan ～はずだ dan ～はずがない untuk menyampaikan perkiraan berdasarkan bukti, jadwal pengiriman, dan verifikasi di kantor.', 'curriculum', 7);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, '233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, 'Kosakata Verifikasi, Jadwal & Pengiriman', 'Kosakata Verifikasi', 'n3-u7-kosakata', 'shield-check', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('666e967d-3950-5f1f-aa44-7e6bf997db39'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat logistik: ご注文の荷物は本日午後に ___ 予定です。', '{"options": ["到着する", "出発する", "注文する", "返品する"], "translation": "Paket pesanan Anda dijadwalkan tiba siang ini.", "sentence_template": "ご注文の荷物は本日午後に [blank] 予定です。"}'::jsonb, '{"selected": "到着する"}'::jsonb, '到着する (touchaku suru) berarti tiba/sampai.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a2c8494e-6be3-55d7-9dfd-5d279968f33f'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk mengecek stok: 倉庫にまだ十分 ___ が残っています。', '{"options": ["在庫", "住所", "領収書", "請求書"], "translation": "Di gudang masih tersisa stok yang cukup.", "sentence_template": "倉庫にまだ十分 [blank] が残っています。"}'::jsonb, '{"selected": "在庫"}'::jsonb, '在庫 (zaiko) berarti persediaan barang/stok.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8a393d80-4334-5273-93b2-fb084bb6b71e'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kantor: 添付ファイルに間違いがないか、もう一度 ___ します。', '{"options": ["確認", "想像", "期待", "延期"], "translation": "Saya akan memeriksa sekali lagi apakah ada kesalahan di file lampiran.", "sentence_template": "添付ファイルに間違いがないか、もう一度 [blank] します。"}'::jsonb, '{"selected": "確認"}'::jsonb, '確認する (kakunin suru) berarti memverifikasi atau memastikan.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3a4cd9bf-3131-5644-9e4b-0feded793f0c'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk jadwal resmi: 電車の ___ によると、次の急行は五分後に来ます。', '{"options": ["時刻表", "案内図", "説明書", "履歴書"], "translation": "Menurut jadwal kereta, kereta ekspres berikutnya datang lima menit lagi.", "sentence_template": "電車の [blank] によると、次の急行は五分後に来ます。"}'::jsonb, '{"selected": "時刻表"}'::jsonb, '時刻表 (jikokuhyou) berarti tabel jadwal keberangkatan transportasi.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a33cfc9e-718b-565f-a941-be9f86ada86d'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana status pengiriman dokumen kontrak menurut pembicara?', '{"audio_text": "昨日の夕方に速達で送りましたので、今日の午前中には先方に届いていると思います。", "options": [{"id": "opt_1", "text": "Kemungkinan sudah sampai di pihak klien pada pagi hari ini"}, {"id": "opt_2", "text": "Baru akan dikirim sore nanti lewat pos kilat"}, {"id": "opt_3", "text": "Tertahan di kantor pos karena alamat kurang lengkap"}, {"id": "opt_4", "text": "Akan diantarkan langsung oleh staf besok pagi"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '今日の午前中には先方に届いていると思います berarti diperkirakan sudah sampai pagi ini.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('777ad999-6b25-5b7e-897f-3f94f565a350'::uuid, '7c4f7f16-ffd3-5f76-a882-72a61da81352'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara yakin ruangan rapat sedang kosong?', '{"audio_text": "予約カレンダーを確認したところ、三時から四時までは誰も使っていませんでした。", "options": [{"id": "opt_1", "text": "Karena lampu ruang rapat terlihat mati dari luar"}, {"id": "opt_2", "text": "Karena di kalender reservasi tidak ada yang memakainya jam tiga sampai empat"}, {"id": "opt_3", "text": "Karena semua pegawai sedang menghadiri seminar luar"}, {"id": "opt_4", "text": "Karena kuncinya masih tergantung di meja resepsionis"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '予約カレンダーを確認したところ...誰も使っていませんでした berarti setelah cek kalender reservasi, tidak ada yang memakainya.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, '233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, 'Pola ～はずだ & ～はずがない', 'Pola Hazu da', 'n3-u7-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bbc7904d-8b7c-5040-a909-589fc33f389f'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi dugaan logis: 彼は十年も日本に住んでいたので、日本語が上手 ___ はずです。', '{"options": ["な", "の", "だ", "に"], "translation": "Karena dia tinggal di Jepang selama sepuluh tahun, bahasa Jepangnya seharusnya mahir.", "sentence_template": "彼は十年も日本に住んでいたので、日本語が上手 [blank] はずです。"}'::jsonb, '{"selected": "な"}'::jsonb, 'Kata sifat-NA (上手) memakai な sebelum はずです.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c5c53da2-bc8d-5732-8b86-81f642a1d16d'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk penyangkalan kuat: 昨日送ったばかりだから、まだ届いている ___ 。', '{"options": ["はずがありません", "はずです", "ようです", "そうです"], "translation": "Karena baru saja dikirim kemarin, tidak mungkin sudah sampai.", "sentence_template": "昨日送ったばかりだから、まだ届いている [blank] 。"}'::jsonb, '{"selected": "はずがありません"}'::jsonb, '～はずがありません berarti ''tidak mungkin secara logis''.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('44bbf2eb-e81b-559e-9218-9ce453dcb9b4'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 今日は祝日なので、銀行は休み ___ はずです。', '{"options": ["の", "な", "だ", "で"], "translation": "Karena hari ini hari libur nasional, bank seharusnya tutup.", "sentence_template": "今日は祝日なので、銀行は休み [blank] はずです。"}'::jsonb, '{"selected": "の"}'::jsonb, 'Nomina (休み) dihubungkan dengan の sebelum はずです.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('21eb8eb0-7c0d-5674-8b54-5f1006860892'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah mengirim email, dia seharusnya tahu."', '{"tokens": ["彼は", "メールを送ったので、", "はずがありません。", "知っている", "知って", "はずです。"], "target_translation": "Karena sudah mengirim email, dia seharusnya tahu.", "romaji": "Meeru o okutta node, kare wa shitte iru hazu desu."}'::jsonb, '["メールを送ったので、", "彼は", "知っている", "はずです。"]'::jsonb, '知っている (bentuk kamus) + はずです menyatakan keyakinan logis.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2b77f4ab-65aa-5b25-a111-650bcbc853b2'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Orang yang begitu teliti tidak mungkin membuat kesalahan."', '{"tokens": ["はずが", "間違えて", "まじめなあの人が", "はずでした。", "間違える", "ありません。"], "target_translation": "Orang yang begitu teliti tidak mungkin membuat kesalahan.", "romaji": "Majimena ano hito ga machigaeru hazu ga arimasen."}'::jsonb, '["まじめなあの人が", "間違える", "はずが", "ありません。"]'::jsonb, '間違える + はずがありません menyatakan ketidakmungkinan berdasarkan sifat orang tersebut.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('70c22de6-57ca-5f43-9ec0-da5bff76254a'::uuid, '48470705-b669-5414-a39e-ecdd7c9f9eda'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'listening', 'listening_choice', 'Apa yang membuat pembicara yakin barang tersebut masih ada di toko?', '{"audio_text": "さっき電話で問い合わせたばかりなので、まだ在庫があるはずです。", "options": [{"id": "opt_1", "text": "Karena produk itu baru saja dirilis hari ini"}, {"id": "opt_2", "text": "Karena pembicara baru saja menanyakannya lewat telepon"}, {"id": "opt_3", "text": "Karena toko tersebut jarang dikunjungi pembeli"}, {"id": "opt_4", "text": "Karena ia melihatnya di situs web kemarin malam"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, 'さっき電話で問い合わせたばかりなので berarti karena baru saja menanyakan lewat telepon tadi.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, '233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, 'Simak & Baca: Dugaan & Kenyataan Berbeda', 'Simak Verifikasi', 'n3-u7-dengar-baca', 'play-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('b67f29f8-0df0-5a73-bf40-81b769b764a5'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang membuat pembicara heran tentang kuncinya?', '{"audio_text": "確かにかばんのポケットに入れたはずなのに、どこを探しても見つかりません。", "options": [{"id": "opt_1", "text": "Ia lupa membawa tasnya dari kantor"}, {"id": "opt_2", "text": "Saku tasnya robek di jalan pulang"}, {"id": "opt_3", "text": "Ia yakin sudah menaruhnya di saku tas, tetapi tidak ketemu di mana pun"}, {"id": "opt_4", "text": "Ia salah membawa kunci milik rekan kerjanya"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '～たはずなのに mengekspresikan keheranan karena kenyataan berbeda dari keyakinan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('99f71e44-5d4f-54b2-8c1a-6dbf4219ea63'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara yakin acara hari ini akan ramai?', '{"audio_text": "事前申し込みが二百人を超えていたので、会場は満席になるはずです。", "options": [{"id": "opt_1", "text": "Karena tiketnya dibagikan gratis di stasiun"}, {"id": "opt_2", "text": "Karena pembicara utamanya adalah aktor terkenal"}, {"id": "opt_3", "text": "Karena ruang acaranya berukuran sangat kecil"}, {"id": "opt_4", "text": "Karena pendaftar awal sudah melebihi dua ratus orang"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '事前申し込みが二百人を超えていたので berarti karena pendaftaran awal melebihi 200 orang.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5d192b05-b2d0-5460-99de-fce0ce1f919c'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara meragukan kabar bahwa restoran itu tutup?', '{"audio_text": "火曜日が定休日だから、今日の水曜日に閉まっているはずがありませんよ。", "options": [{"id": "opt_1", "text": "Karena hari libur tetapnya hari Selasa, jadi tidak mungkin tutup hari Rabu"}, {"id": "opt_2", "text": "Karena ia baru saja makan di sana satu jam lalu"}, {"id": "opt_3", "text": "Karena restoran itu buka dua puluh empat jam setiap hari"}, {"id": "opt_4", "text": "Karena pemiliknya tidak pernah mengambil hari libur"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '火曜日が定休日だから、今日の水曜日に閉まっているはずがありません berarti liburnya Selasa, tidak mungkin tutup hari Rabu.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('facf6665-61dc-5352-b0bd-9ee793553b58'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'reading', 'fill_blank', 'Pilih pola ekspektasi tak terpenuhi: 三時に着く ___ なのに、まだ到着しません。', '{"options": ["はず", "おかげ", "せい", "うち"], "translation": "Padahal seharusnya tiba pukul tiga, tetapi belum juga datang.", "sentence_template": "三時に着く [blank] なのに、まだ到着しません。"}'::jsonb, '{"selected": "はず"}'::jsonb, '～はずなのに berarti ''padahal seharusnya...''.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0379e01d-4f10-5a60-89da-7b733034b4cc'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi bentuk lampau dugaan: 彼は今日休むと聞いていたので、来ない ___ でした。', '{"options": ["はず", "こと", "よう", "ため"], "translation": "Karena saya dengar dia libur hari ini, seharusnya dia tidak datang.", "sentence_template": "彼は今日休むと聞いていたので、来ない [blank] でした。"}'::jsonb, '{"selected": "はず"}'::jsonb, '～はずでした menyatakan ekspektasi sebelumnya yang ternyata berbeda.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('3d446e75-1f7d-56b1-97c6-c229a3a4f003'::uuid, 'b4ece5a6-ac40-5598-9558-bdb3e313d439'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 説明書をよく読めば、誰でも使える ___ です。', '{"options": ["はず", "せい", "ばかり", "うち"], "translation": "Jika membaca buku panduan dengan baik, siapa pun seharusnya bisa memakainya.", "sentence_template": "説明書をよく読めば、誰でも使える [blank] です。"}'::jsonb, '{"selected": "はず"}'::jsonb, '使える (bisa memakai) + はずです menyatakan kesimpulan logis.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, '233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, 'Bicara & Rakit Pernyataan Logis', 'Bicara Logis', 'n3-u7-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a3e6ec8d-4efd-5d30-92fa-52ba9808b029'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kereta berikutnya seharusnya tiba lima menit lagi."', '{"display_text": "次の電車は五分後に着くはずです。", "romaji": "Tsugi no densha wa gofungo ni tsuku hazu desu.", "phonetic_breakdown": ["tsu-gi no", "den-sha wa", "go-fun-go ni", "tsu-ku", "ha-zu de-su"]}'::jsonb, '{"expected_transcript": "次の電車は五分後に着くはずです。"}'::jsonb, 'Ucapkan 五分後 (gofungo) dan 着くはずです dengan intonasi tegas namun sopan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('f31ce1a0-11b4-5b54-a62f-e826a0b0f100'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak mungkin ada kesalahan pada data ini."', '{"display_text": "このデータに間違いがあるはずがありません。", "romaji": "Kono deeta ni machigai ga aru hazu ga arimasen.", "phonetic_breakdown": ["ko-no dee-ta ni", "ma-chi-ga-i ga", "a-ru", "ha-zu ga", "a-ri-ma-sen"]}'::jsonb, '{"expected_transcript": "このデータに間違いがあるはずがありません。"}'::jsonb, '～はずがありません menunjukkan keyakinan kuat bahwa sesuatu mustahil terjadi.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a8637362-127a-5267-a1d9-e7533168c674'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Padahal saya yakin sudah menyimpannya, tetapi filenya hilang."', '{"display_text": "保存したはずなのに、ファイルが消えています。", "romaji": "Hozon shita hazu na noni, fairu ga kiete imasu.", "phonetic_breakdown": ["ho-zon shi-ta", "ha-zu na no-ni", "fa-i-ru ga", "ki-e-te i-ma-su"]}'::jsonb, '{"expected_transcript": "保存したはずなのに、ファイルが消えています。"}'::jsonb, '保存する (hozon suru) berarti menyimpan data/file.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('77078e02-d53f-59ab-b540-437e8ce790c4'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Dokumen itu seharusnya ada di atas meja."', '{"tokens": ["あって", "机の上に", "ある", "はずがありません。", "その書類は", "はずです。"], "target_translation": "Dokumen itu seharusnya ada di atas meja.", "romaji": "Sono shorui wa tsukue no ue ni aru hazu desu."}'::jsonb, '["その書類は", "机の上に", "ある", "はずです。"]'::jsonb, 'ある + はずです menyatakan perkiraan lokasi berdasarkan ingatan/fakta.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('31dda654-a390-5e90-a990-fe46ecdc0b05'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah berlatih keras, ujiannya seharusnya lulus."', '{"tokens": ["合格できて", "はずです。", "合格できる", "一生懸命", "せいです。", "練習したので、"], "target_translation": "Karena sudah berlatih keras, ujiannya seharusnya lulus.", "romaji": "Isshoukenmei renshuu shita node, goukaku dekiru hazu desu."}'::jsonb, '["一生懸命", "練習したので、", "合格できる", "はずです。"]'::jsonb, '合格できる (bisa lulus) + はずです.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fac4ebec-6104-5bb7-80dd-e04ac28eb2da'::uuid, '9665eb31-9ed9-5bad-9c99-ba98331aef40'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Anak kecil tidak mungkin mengerti kanji sesulit ini."', '{"tokens": ["わかって", "ありません。", "はずが", "こんな難しい漢字が", "子どもに", "わかる", "はずです。"], "target_translation": "Anak kecil tidak mungkin mengerti kanji sesulit ini.", "romaji": "Konna muzukashii kanji ga kodomo ni wakaru hazu ga arimasen."}'::jsonb, '["こんな難しい漢字が", "子どもに", "わかる", "はずが", "ありません。"]'::jsonb, 'わかる + はずがありません menegaskan ketidakmungkinan logis.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, '233fdb02-aded-57bc-9503-e0e9087bf338'::uuid, 'Evaluasi Unit 7: Logika & Verifikasi', 'Tes Unit 7', 'n3-u7-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('205ab222-250b-5cbb-aaa1-9c3a54af84c3'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang tepat: もう十時なので、そろそろ彼が到着 ___ はずです。', '{"options": ["する", "して", "します", "しよう"], "translation": "Karena sudah jam sepuluh, sebentar lagi dia seharusnya tiba.", "sentence_template": "もう十時なので、そろそろ彼が到着 [blank] はずです。"}'::jsonb, '{"selected": "する"}'::jsonb, 'Bentuk kamus 到着する langsung diikuti はずです.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bafd4667-72e2-5706-bb05-f32afc18bbdf'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk penyangkalan logis: 鍵をかけたので、誰かが入れる ___ がありません。', '{"options": ["はず", "こと", "よう", "ため"], "translation": "Karena sudah dikunci, tidak mungkin ada orang yang bisa masuk.", "sentence_template": "鍵をかけたので、誰かが入れる [blank] がありません。"}'::jsonb, '{"selected": "はず"}'::jsonb, '入れるはずがありません berarti tidak mungkin bisa masuk.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e1b5a376-f465-5067-9b97-b5028166c9c3'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara yakin rapat akan selesai sebelum pukul lima?', '{"audio_text": "議題は二つだけですから、五時までには終わるはずです。", "options": [{"id": "opt_1", "text": "Karena pesertanya hanya tiga orang"}, {"id": "opt_2", "text": "Karena ruang rapat harus dikosongkan pukul lima"}, {"id": "opt_3", "text": "Karena agendanya hanya ada dua topik"}, {"id": "opt_4", "text": "Karena pimpinan rapat akan pergi dinas sore ini"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '議題は二つだけですから berarti karena agenda rapatnya hanya dua.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d113c0ec-f8f7-578f-8d47-cec7ac89c537'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'listening', 'listening_choice', 'Apa yang mengherankan pembicara tentang AC ruangan?', '{"audio_text": "さっき温度を下げたはずなのに、部屋がぜんぜん涼しくなりません。", "options": [{"id": "opt_1", "text": "AC ruangan berbunyi sangat keras"}, {"id": "opt_2", "text": "Tagihan listrik bulan ini naik drastis"}, {"id": "opt_3", "text": "Pengendali jarak jauh AC hilang dari meja"}, {"id": "opt_4", "text": "Padahal suhunya sudah diturunkan, ruangan tidak kunjung sejuk"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '温度を下げたはずなのに、ぜんぜん涼しくなりません berarti padahal sudah menurunkan suhu, tidak dingin sama sekali.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7b74f433-032c-5aa4-b24b-ad9e7c84b6aa'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena hari ini hari Minggu, kantor seharusnya libur."', '{"tokens": ["今日は日曜日だから、", "はずです。", "休みの", "はずがありません。", "休みな", "会社は"], "target_translation": "Karena hari ini hari Minggu, kantor seharusnya libur.", "romaji": "Kyou wa nichiyoubi da kara, kaisha wa yasumi no hazu desu."}'::jsonb, '["今日は日曜日だから、", "会社は", "休みの", "はずです。"]'::jsonb, 'Nomina 休み + の + はずです.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('92fbbc15-ff71-5c8f-ae32-988b792c226c'::uuid, '06e6d1cd-de9a-524d-bb58-c8d488e1137f'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Paket itu seharusnya sampai besok pagi."', '{"display_text": "その荷物は明日の午前中に届くはずです。", "romaji": "Sono nimotsu wa ashita no gozenchuu ni todoku hazu desu.", "phonetic_breakdown": ["so-no ni-mo-tsu wa", "a-shi-ta no", "go-zen-chuu ni", "to-do-ku", "ha-zu de-su"]}'::jsonb, '{"expected_transcript": "その荷物は明日の午前中に届くはずです。"}'::jsonb, '午前中 (gozenchuu) berarti sepanjang pagi hingga jam 12 siang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, v_level_id, 'Bentuk Pasif (～られる)', 'Pahami kalimat pasif bahasa Jepang untuk berita resmi, evaluasi kerja, serta pasif penderitaan dalam pengalaman sehari-hari.', 'curriculum', 8);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, '2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, 'Kosakata Berita, Evaluasi & Pengalaman', 'Kosakata Berita', 'n3-u8-kosakata', 'buildings', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fc0dce68-56b1-575a-85f4-953d478d5612'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi kerja: 丁寧な仕事ぶりが上司に高く ___ しました。', '{"options": ["評価", "誤解", "批判", "延期"], "translation": "Cara kerja yang teliti mendapat penilaian tinggi dari atasan (aktif: atasan menilai tinggi).", "sentence_template": "丁寧な仕事ぶりが上司に高く [blank] しました。"}'::jsonb, '{"selected": "評価"}'::jsonb, '評価 (hyouka) berarti penilaian/apresiasi. Bentuk pasifnya adalah 評価されました.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d837898b-abb0-5dcb-83dd-e30c245ae032'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk acara resmi: 来月、国際会議が東京で ___ されます。', '{"options": ["開催", "破壊", "解決", "発見"], "translation": "Bulan depan, konferensi internasional akan diselenggarakan di Tokyo.", "sentence_template": "来月、国際会議が東京で [blank] されます。"}'::jsonb, '{"selected": "開催"}'::jsonb, '開催される (kaisai sareru) berarti diselenggarakan (untuk acara/konferensi).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c82bdea5-57f6-5baf-b3ae-05706a4e50f8'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita produk: この自動車は日本の工場で ___ されています。', '{"options": ["製造", "想像", "放送", "清掃"], "translation": "Mobil ini diproduksi di pabrik Jepang.", "sentence_template": "この自動車は日本の工場で [blank] されています。"}'::jsonb, '{"selected": "製造"}'::jsonb, '製造される (seizou sareru) berarti diproduksi/dibuat di pabrik.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('af2ce788-fa88-5328-9be1-499539374f61'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk insiden harian: 満員電車の中で足を ___ しまいました。', '{"options": ["踏まれて", "押して", "投げて", "洗って"], "translation": "Di dalam kereta yang penuh sesak, kaki saya terinjak.", "sentence_template": "満員電車の中で足を [blank] しまいました。"}'::jsonb, '{"selected": "踏まれて"}'::jsonb, '踏む (menginjak) -> bentuk pasif 踏まれる (diinjak).', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('11aea64e-8acc-5c18-877a-6501850e0dec'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'listening', 'listening_choice', 'Berita apa yang disampaikan tentang bangunan bersejarah tersebut?', '{"audio_text": "このお城はおよそ四百年前に建てられ、今でも多くの観光客に親しまれています。", "options": [{"id": "opt_1", "text": "Kastel itu dibangun sekitar 400 tahun lalu dan masih digemari wisatawan"}, {"id": "opt_2", "text": "Kastel itu akan direnovasi total mulai tahun depan"}, {"id": "opt_3", "text": "Kastel itu baru dibuka untuk umum bulan lalu"}, {"id": "opt_4", "text": "Kastel itu tutup sementara karena badai"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '四百年前に建てられ (dibangun 400 tahun lalu) dan 親しまれています (digemari/dicintai).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('cb4fef26-eac3-5230-86c7-937bdf14c445'::uuid, 'a37e6061-234d-5f7e-88ef-5d252e066442'::uuid, NULL, 'listening', 'listening_choice', 'Pengalaman kurang menyenangkan apa yang dialami pembicara kemarin?', '{"audio_text": "帰り道で急に雨に降られて、新しい靴がびしょ濡れになってしまいました。", "options": [{"id": "opt_1", "text": "Ia kehilangan payung di dalam bus"}, {"id": "opt_2", "text": "Ia kehujanan tiba-tiba di jalan pulang sehingga sepatu barunya basah kuyup"}, {"id": "opt_3", "text": "Ia terpeleset di tangga stasiun karena lantai licin"}, {"id": "opt_4", "text": "Sepatu barunya tertukar di ruang pertemuan"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '雨に降られて (kehujanan, bentuk pasif penderitaan) membuat sepatu barunya basah kuyup.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('9732e753-78c3-50a3-b666-22a5adc66314'::uuid, '2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, 'Pola Pasif Langsung & Pasif Penderitaan', 'Pola Pasif', 'n3-u8-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a657d071-c59a-5004-b2d5-1fc18bbeca23'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'reading', 'fill_blank', 'Ubah ほめる (memuji) ke bentuk pasif: 発表がうまくいって、先生に ___ 。', '{"options": ["ほめられました", "ほめました", "ほめさせました", "ほめられましたか"], "translation": "Presentasinya berjalan lancar, sehingga saya dipuji oleh guru.", "sentence_template": "発表がうまくいって、先生に [blank] 。"}'::jsonb, '{"selected": "ほめられました"}'::jsonb, 'Verba Golongan II ほめる -> buang る + られる -> ほめられました (dipuji).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5ca91520-a353-5fd3-9d63-48ce06b47600'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'reading', 'fill_blank', 'Ubah たのむ (meminta) ke bentuk pasif: 部長に急な仕事を ___ ました。', '{"options": ["頼まれ", "頼み", "頼ませ", "頼んで"], "translation": "Saya dimintai pekerjaan mendadak oleh kepala bagian.", "sentence_template": "部長に急な仕事を [blank] ました。"}'::jsonb, '{"selected": "頼まれ"}'::jsonb, 'Verba Golongan I 頼む (tanomu) -> ubah vokal u ke a + れる -> 頼まれる (diminta).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a7134c2a-e509-5cb2-9d43-70dbbc0de0bb'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk pasif dari くる (datang): 忙しいときに友達に ___ て困りました。', '{"options": ["来られ", "来させ", "来", "来て"], "translation": "Saat sedang sibuk, saya kedatangan teman dan merasa kerepotan.", "sentence_template": "忙しいときに友達に [blank] て困りました。"}'::jsonb, '{"selected": "来られ"}'::jsonb, 'Bentuk pasif tidak beraturan dari 来る (kuru) adalah 来られる (korareru).', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('9f625830-4ccf-5dad-9318-9796a5de0cb9'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Buku ini dibaca di seluruh dunia."', '{"tokens": ["この本は", "読んで", "います。", "読まれて", "読ませて", "世界中で"], "target_translation": "Buku ini dibaca di seluruh dunia.", "romaji": "Kono hon wa sekaijuu de yomarete imasu."}'::jsonb, '["この本は", "世界中で", "読まれて", "います。"]'::jsonb, '読む -> 読まれる (dibaca). 読まれています menunjukkan keadaan yang berlangsung luas.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('368a3906-e805-56be-a27d-0fecf12c45c5'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya dipuji oleh atasan."', '{"tokens": ["私は", "ほめられました。", "ほめました。", "上司に", "上司を"], "target_translation": "Saya dipuji oleh atasan.", "romaji": "Watashi wa joushi ni homeraremashita."}'::jsonb, '["私は", "上司に", "ほめられました。"]'::jsonb, 'Pelaku dalam kalimat pasif ditandai dengan partikel に (上司に).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d75fa00a-5574-5a8c-8250-61c86ab089e9'::uuid, '9732e753-78c3-50a3-b666-22a5adc66314'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'listening', 'listening_choice', 'Apa yang terjadi pada sepeda milik pembicara?', '{"audio_text": "駅の前に止めておいた自転車が誰かに盗まれてしまいました。", "options": [{"id": "opt_1", "text": "Dipindahkan petugas ke tempat parkir lain"}, {"id": "opt_2", "text": "Bannya bocor saat diparkir di depan stasiun"}, {"id": "opt_3", "text": "Dicuri oleh seseorang saat diparkir di depan stasiun"}, {"id": "opt_4", "text": "Dipinjam oleh adiknya tanpa izin"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '誰かに盗まれてしまいました berarti telah dicuri oleh seseorang.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, '2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, 'Simak & Baca: Kalimat Pasif di Berita & Kantor', 'Simak Pasif', 'n3-u8-dengar-baca', 'play-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a0dc65a1-2857-5504-bd4e-aefe57f8c478'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana kebijakan baru perusahaan diumumkan?', '{"audio_text": "新しい勤務ルールは、昨日の全社ミーティングで正式に発表されました。", "options": [{"id": "opt_1", "text": "Dikirim melalui surat pos ke rumah masing-masing pegawai"}, {"id": "opt_2", "text": "Ditempel di papan pengumuman kantin saja"}, {"id": "opt_3", "text": "Akan dibahas ulang pada rapat bulan depan"}, {"id": "opt_4", "text": "Diumumkan secara resmi pada rapat seluruh perusahaan kemarin"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '昨日の全社ミーティングで正式に発表されました berarti diumumkan resmi di rapat seluruh perusahaan kemarin.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('65aa531c-a78b-5de7-8f02-ad2ad7e55102'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa kesal di bioskop kemarin?', '{"audio_text": "映画を見ている間、後ろの人に何度も椅子を蹴られて集中できませんでした。", "options": [{"id": "opt_1", "text": "Kursinya berkali-kali ditendang oleh orang di belakangnya"}, {"id": "opt_2", "text": "Orang di sampingnya terus berbicara lewat telepon"}, {"id": "opt_3", "text": "Layar bioskop sempat mati di tengah film"}, {"id": "opt_4", "text": "Tempat duduknya ditempati oleh penonton lain"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '後ろの人に何度も椅子を蹴られて berarti kursinya berkali-kali ditendang orang di belakang.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a477fb85-d7c3-58a6-aa22-06942e95240b'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang terjadi pada usulan yang diajukan tim pembicara?', '{"audio_text": "先月提出した企画案が役員会議で承認され、来月から実行に移されます。", "options": [{"id": "opt_1", "text": "Ditolak karena melebihi anggaran"}, {"id": "opt_2", "text": "Disetujui di rapat direksi dan akan dijalankan mulai bulan depan"}, {"id": "opt_3", "text": "Diminta untuk direvisi kembali selama dua minggu"}, {"id": "opt_4", "text": "Digabungkan dengan proyek dari cabang lain"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '役員会議で承認され (disetujui di rapat direksi) dan 実行に移されます (dijalankan).', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ecb4b2ff-4046-5d04-afdb-fbe8edcf4ee1'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif dari 使う (memakai): この言葉はビジネスシーンでよく ___ ています。', '{"options": ["使われ", "使い", "使わせ", "使って"], "translation": "Kata ini sering digunakan dalam situasi bisnis.", "sentence_template": "この言葉はビジネスシーンでよく [blank] ています。"}'::jsonb, '{"selected": "使われ"}'::jsonb, 'Verba Golongan I berakhiran う (使う) berubah menjadi わ + れる -> 使われる.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c150ce8f-505e-5eee-b0fc-1f57aa44670f'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'reading', 'fill_blank', 'Pilih partikel pelaku pasif karya: この小説は有名な作家 ___ 書かれました。', '{"options": ["によって", "について", "にとって", "に対して"], "translation": "Novel ini ditulis oleh penulis terkenal.", "sentence_template": "この小説は有名な作家 [blank] 書かれました。"}'::jsonb, '{"selected": "によって"}'::jsonb, 'Untuk pencipta karya/penemuan dalam kalimat pasif, gunakan によって sebagai penanda pelaku.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('497fd7d4-1f86-5095-b506-85381d4240fc'::uuid, '6bf68045-dff9-56f4-8298-d0dd413b90b6'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi pasif penderitaan: 弟に大切なパソコンを ___ てしまいました。', '{"options": ["壊され", "壊し", "壊させ", "壊れ"], "translation": "Komputer penting saya dirusak oleh adik laki-laki.", "sentence_template": "弟に大切なパソコンを [blank] てしまいました。"}'::jsonb, '{"selected": "壊され"}'::jsonb, '壊す (merusak) -> pasif 壊される (dirusak).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('348683d9-8f16-52e1-80bd-086768e2398c'::uuid, '2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, 'Bicara & Rakit Pengalaman Pasif', 'Bicara Pasif', 'n3-u8-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('34cc4084-53c7-5de3-aef1-30c539b98679'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya diminta tolong oleh senior."', '{"display_text": "先輩に仕事を頼まれました。", "romaji": "Senpai ni shigoto o tanomaremashita.", "phonetic_breakdown": ["sen-pa-i ni", "shi-go-to o", "ta-no-ma-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "先輩に仕事を頼まれました。"}'::jsonb, '頼まれました adalah bentuk pasif lampau sopan dari 頼む (meminta).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('455777bf-28c3-5b87-8943-96f8e6ffbc63'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya kehujanan dalam perjalanan pulang."', '{"display_text": "帰る途中で雨に降られました。", "romaji": "Kaeru tochuu de ame ni furaremashita.", "phonetic_breakdown": ["ka-e-ru", "to-chuu de", "a-me ni", "fu-ra-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "帰る途中で雨に降られました。"}'::jsonb, '雨に降られる adalah bentuk pasif khas Jepang untuk menyatakan kerugian/ketidaknyamanan karena hujan.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('73d7d2bc-ff44-52c0-a611-00f9c5d67bf5'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapat tahunan diselenggarakan setiap bulan Maret."', '{"display_text": "年次会議は毎年三月に開催されます。", "romaji": "Nenji kaigi wa maitoshi sangatsu ni kaisai saremasu.", "phonetic_breakdown": ["nen-ji ka-i-gi wa", "ma-i-to-shi", "san-ga-tsu ni", "ka-i-sa-i", "sa-re-ma-su"]}'::jsonb, '{"expected_transcript": "年次会議は毎年三月に開催されます。"}'::jsonb, 'Verba する berubah menjadi される pada bentuk pasif (開催する -> 開催される).', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('29cec591-b036-56ab-8dee-33969a91d759'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya diundang ke pesta pernikahan teman."', '{"tokens": ["されました。", "しました。", "友達の結婚式に", "させました。", "招待"], "target_translation": "Saya diundang ke pesta pernikahan teman.", "romaji": "Tomodachi no kekkonshiki ni shoutai saremashita."}'::jsonb, '["友達の結婚式に", "招待", "されました。"]'::jsonb, '招待する (mengundang) -> 招待されました (diundang).', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5c4db2aa-b3a6-52fd-9ef3-2b5fb2ecc9c6'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Kue yang saya simpan dimakan oleh kakak."', '{"tokens": ["食べられました。", "兄に", "食べました。", "とっておいたケーキを", "兄が"], "target_translation": "Kue yang saya simpan dimakan oleh kakak.", "romaji": "Tottte oita keeki o ani ni taberaremashita."}'::jsonb, '["とっておいたケーキを", "兄に", "食べられました。"]'::jsonb, '食べられました menyatakan pengalaman dirugikan karena kue dimakan kakak.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('57955355-fd20-56ed-b173-50104262f71a'::uuid, '348683d9-8f16-52e1-80bd-086768e2398c'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Produk ini dijual di seluruh Jepang."', '{"tokens": ["この商品は", "日本中で", "販売して", "販売させて", "います。", "販売されて"], "target_translation": "Produk ini dijual di seluruh Jepang.", "romaji": "Kono shouhin wa nihonjuu de hanbai sarete imasu."}'::jsonb, '["この商品は", "日本中で", "販売されて", "います。"]'::jsonb, '販売する (menjual) -> 販売されています (dijual).', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, '2f556335-b5a4-5d61-b196-8532421fe1f2'::uuid, 'Evaluasi Unit 8: Penguasaan Pasif', 'Tes Unit 8', 'n3-u8-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4bfe6964-5f1a-5e23-8ff0-0ee78f3bc72d'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'reading', 'fill_blank', 'Ubah 選ぶ (memilih) ke bentuk pasif: 彼女がチームの代表に ___ ました。', '{"options": ["選ばれ", "選び", "選ばせ", "選んで"], "translation": "Dia terpilih sebagai perwakilan tim.", "sentence_template": "彼女がチームの代表に [blank] ました。"}'::jsonb, '{"selected": "選ばれ"}'::jsonb, '選ぶ (Golongan I) -> 選ばれる (dipilih/terpilih).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('519dd71b-35be-5fcc-a0b0-91f762040398'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk pasif yang tepat: 駅で外国人に道を ___ ました。', '{"options": ["聞かれ", "聞き", "聞かせ", "聞いて"], "translation": "Di stasiun saya ditanya arah jalan oleh orang asing.", "sentence_template": "駅で外国人に道を [blank] ました。"}'::jsonb, '{"selected": "聞かれ"}'::jsonb, '聞く (bertanya) -> 聞かれる (ditanya).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('20430138-6e2e-54d0-b0a2-4db042a60686'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'listening', 'listening_choice', 'Apa yang terjadi pada gedung lama di dekat stasiun?', '{"audio_text": "駅前の古いビルは来月取り壊され、新しく商業施設が建てられる予定です。", "options": [{"id": "opt_1", "text": "Akan dijadikan museum sejarah kota"}, {"id": "opt_2", "text": "Akan dijual kepada perusahaan asing"}, {"id": "opt_3", "text": "Akan dirobohkan bulan depan dan diganti fasilitas komersial baru"}, {"id": "opt_4", "text": "Akan ditutup sementara untuk pengecatan ulang"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '取り壊され (dirobohkan) dan 新しく商業施設が建てられる (akan dibangun fasilitas komersial baru).', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('91a2adc8-74f9-560e-b41e-7dd4d920a91e'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara kurang tidur semalam?', '{"audio_text": "夜中に隣の部屋で大きな音楽をかけられて、ぜんぜん眠れませんでした。", "options": [{"id": "opt_1", "text": "Karena ia harus menyelesaikan laporan sampai pagi"}, {"id": "opt_2", "text": "Karena kucing peliharaannya terus mengeong"}, {"id": "opt_3", "text": "Karena jendela kamarnya rusak tertiup angin"}, {"id": "opt_4", "text": "Karena kamar sebelah memutar musik keras di tengah malam"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '大きな音楽をかけられて adalah pasif penderitaan: terganggu karena tetangga memutar musik keras.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e893fb12-807a-5203-bcf3-38ed868a5d13'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Usulan saya diterima dengan baik oleh manajer."', '{"tokens": ["課長に", "認められました。", "課長を", "認めました。", "私の提案は"], "target_translation": "Usulan saya diterima dengan baik oleh manajer.", "romaji": "Watashi no teian wa kachou ni mitomeraremashita."}'::jsonb, '["私の提案は", "課長に", "認められました。"]'::jsonb, '認める (mengakui/menerima) -> 認められました (diakui/diterima).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ac7d7521-adc3-5a41-af08-c9c4a7b26767'::uuid, '6bac56d7-df94-5c98-a050-d6344df8763a'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-008' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bahasa Jepang dipelajari oleh banyak orang."', '{"display_text": "日本語は多くの人に学ばれています。", "romaji": "Nihongo wa ooku no hito ni manabarete imasu.", "phonetic_breakdown": ["ni-hon-go wa", "oo-ku no hi-to ni", "ma-na-ba-re-te", "i-ma-su"]}'::jsonb, '{"expected_transcript": "日本語は多くの人に学ばれています。"}'::jsonb, '学ぶ (manabu = belajar) berubah menjadi 学ばれる (dipelajari).', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, v_level_id, 'Baru Saja (～たばかり)', 'Ceritakan adaptasi lingkungan baru, pindah rumah, dan pengalaman awal kerja di Jepang menggunakan pola ～たばかり.', 'curriculum', 9);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, '8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, 'Kosakata Pindah, Masuk Kerja & Adaptasi', 'Kosakata Adaptasi', 'n3-u9-kosakata', 'compass', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('5d2a8379-b678-5eae-bf19-4896ff38b8be'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat awal karier: 今年の四月にこの会社へ ___ しました。', '{"options": ["入社", "退社", "出張", "見学"], "translation": "Pada bulan April tahun ini saya masuk bergabung di perusahaan ini.", "sentence_template": "今年の四月にこの会社へ [blank] しました。"}'::jsonb, '{"selected": "入社"}'::jsonb, '入社 (nyuusha) berarti masuk menjadi karyawan suatu perusahaan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('dc4b607c-f22c-5887-8089-8530eb619b9a'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk pindahan: 先週末に新しいアパートへ ___ しました。', '{"options": ["引っ越し", "旅行", "散歩", "帰国"], "translation": "Akhir pekan lalu saya pindah ke apartemen baru.", "sentence_template": "先週末に新しいアパートへ [blank] しました。"}'::jsonb, '{"selected": "引っ越し"}'::jsonb, '引っ越し (hikkoshi) berarti pindahan tempat tinggal.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c4dd356b-6213-5709-8127-b734d946227e'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat adaptasi: 新しい生活にまだ十分 ___ ていません。', '{"options": ["慣れ", "忘れ", "晴れ", "壊れ"], "translation": "Saya belum cukup terbiasa dengan kehidupan baru.", "sentence_template": "新しい生活にまだ十分 [blank] ていません。"}'::jsonb, '{"selected": "慣れ"}'::jsonb, '慣れる (nareru) berarti terbiasa. 慣れていません = belum terbiasa.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('309550ca-c175-56ac-92ac-a7de1209b4eb'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk kelulusan: 先月大学を ___ して、今は研修を受けています。', '{"options": ["卒業", "入学", "休学", "留学"], "translation": "Bulan lalu saya lulus universitas, dan sekarang sedang mengikuti pelatihan.", "sentence_template": "先月大学を [blank] して、今は研修を受けています。"}'::jsonb, '{"selected": "卒業"}'::jsonb, '卒業する (sotsugyou suru) berarti lulus dari sekolah/universitas.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e7c1100b-6f97-5838-b2e0-e36ce831b7d6'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana kondisi apartemen baru pembicara saat ini?', '{"audio_text": "先週引っ越してきたので、部屋にはまだ開けていない段ボールがたくさん残っています。", "options": [{"id": "opt_1", "text": "Masih banyak kardus pindahan yang belum dibuka di kamar"}, {"id": "opt_2", "text": "Semua perabot sudah tertata rapi sejak hari pertama"}, {"id": "opt_3", "text": "Ia sedang mencari teman sekamar untuk berbagi sewa"}, {"id": "opt_4", "text": "Listrik dan internetnya belum tersambung"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'まだ開けていない段ボールがたくさん残っています berarti masih banyak kardus yang belum dibuka.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8b691b4e-c593-510e-9227-52e6fb9fb7ab'::uuid, '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99'::uuid, NULL, 'listening', 'listening_choice', 'Apa kesulitan awal yang dialami pembicara di divisi baru?', '{"audio_text": "配属されて間もないので、社内の専門用語や手続きの流れを覚えるのに苦労しています。", "options": [{"id": "opt_1", "text": "Jarak tempuh ke kantor terlalu jauh dari rumah"}, {"id": "opt_2", "text": "Kesulitan menghafal istilah khusus dan alur prosedur internal"}, {"id": "opt_3", "text": "Jadwal makan siang terlalu singkat"}, {"id": "opt_4", "text": "Komputer kantornya belum terpasang perangkat lunak"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '社内の専門用語や手続きの流れを覚えるのに苦労しています berarti kesulitan menghafal istilah khusus dan alur prosedur kantor.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, '8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, 'Pola ～たばかり & ～たばかりの', 'Pola Ta Bakari', 'n3-u9-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a3727adb-181c-5656-9212-873e5e67dcea'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat baru datang: 先月日本に ___ ばかりなので、まだ道がわかりません。', '{"options": ["来た", "来る", "来て", "来ます"], "translation": "Karena baru saja datang ke Jepang bulan lalu, saya belum tahu jalan.", "sentence_template": "先月日本に [blank] ばかりなので、まだ道がわかりません。"}'::jsonb, '{"selected": "来た"}'::jsonb, 'Pola ～たばかり selalu memakai verba Bentuk-TA (来たばかり).', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('05af24c7-1b33-51f9-83ad-0a5fe04f81d1'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'reading', 'fill_blank', 'Pilih penghubung sebelum nomina: これは昨日 ___ ばかりのパソコンです。', '{"options": ["買った", "買う", "買って", "買います"], "translation": "Ini adalah laptop yang baru saja dibeli kemarin.", "sentence_template": "これは昨日 [blank] ばかりのパソコンです。"}'::jsonb, '{"selected": "買った"}'::jsonb, 'Verba Bentuk-TA + ばかりの + Nomina (買ったばかりのパソコン).', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d288d714-4f91-54fa-8747-5a00a5684117'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk penghubung alasan: 入社したばかり ___ 、わからないことが多いです。', '{"options": ["なので", "のので", "だので", "でので"], "translation": "Karena baru saja masuk kerja, banyak hal yang belum saya ketahui.", "sentence_template": "入社したばかり [blank] 、わからないことが多いです。"}'::jsonb, '{"selected": "なので"}'::jsonb, 'ばかり berperilaku seperti nomina/adjektiva-NA sebelum ので -> ばかりなので.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('562dbef8-6750-56ab-ba69-ed128244fac4'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya baru saja selesai makan siang."', '{"tokens": ["食べた", "食べて", "食べる", "昼ごはんを", "ばかりです。"], "target_translation": "Saya baru saja selesai makan siang.", "romaji": "Hirugohan o tabeta bakari desu."}'::jsonb, '["昼ごはんを", "食べた", "ばかりです。"]'::jsonb, '食べた (Bentuk-TA) + ばかりです berarti baru saja makan.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('6a114fcb-c63d-5418-94b6-398c3e5cb1da'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Ini adalah toko yang baru saja dibuka bulan ini."', '{"tokens": ["ばかりな", "店です。", "今月オープンした", "ばかりの", "オープンして", "これは"], "target_translation": "Ini adalah toko yang baru saja dibuka bulan ini.", "romaji": "Kore wa kongetsu oopun shita bakari no mise desu."}'::jsonb, '["これは", "今月オープンした", "ばかりの", "店です。"]'::jsonb, 'Saat menerangkan nomina (店), gunakan ばかりの (bukan ばかりな).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d4ee9af0-1b72-5329-866b-8dd18985361e'::uuid, '0df92274-024d-5e39-8c25-fda92ab32f74'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara menolak ajakan minum kopi sekarang?', '{"audio_text": "すみません、さっき食堂でコーヒーを飲んだばかりなんです。", "options": [{"id": "opt_1", "text": "Karena dokter melarangnya minum kafein"}, {"id": "opt_2", "text": "Karena ia harus segera menghadiri rapat dengan klien"}, {"id": "opt_3", "text": "Karena ia baru saja minum kopi di kantin tadi"}, {"id": "opt_4", "text": "Karena ia tidak menyukai rasa kopi di mesin kantor"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, 'さっき食堂でコーヒーを飲んだばかりなんです berarti baru saja minum kopi di kantin tadi.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, '8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, 'Simak & Baca: Pengalaman Awal di Jepang', 'Simak Pengalaman', 'n3-u9-dengar-baca', 'chats-circle', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('40f871bf-6c9a-590d-b57f-ac60c45c32f4'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa pembicara belum bisa mengemudi dengan lancar?', '{"audio_text": "先月運転免許を取ったばかりなので、まだ高速道路を走るのは怖いです。", "options": [{"id": "opt_1", "text": "Karena mobilnya sedang diperbaiki di bengkel"}, {"id": "opt_2", "text": "Karena rambu lalu lintas di daerahnya sedang diganti"}, {"id": "opt_3", "text": "Karena jalan tol sedang ditutup akibat salju"}, {"id": "opt_4", "text": "Karena ia baru saja mendapatkan SIM bulan lalu"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '先月運転免許を取ったばかりなので berarti karena baru saja memperoleh SIM bulan lalu.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('9bd4a43b-b917-5b73-a205-4cd383d1f764'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang membuat pembicara merasa kecewa dengan ponselnya?', '{"audio_text": "先週買ったばかりのスマホを落として、画面にひびが入ってしまいました。", "options": [{"id": "opt_1", "text": "Ponsel yang baru dibelinya minggu lalu jatuh dan layarnya retak"}, {"id": "opt_2", "text": "Baterai ponsel barunya cepat habis dalam dua jam"}, {"id": "opt_3", "text": "Ponsel barunya tertinggal di kereta pulang"}, {"id": "opt_4", "text": "Toko salah mengirimkan warna ponsel yang dipesan"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '先週買ったばかりのスマホを落として、画面にひびが入ってしまいました berarti menjatuhkan ponsel baru dan layarnya retak.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('60cf7427-3b5d-5033-a0d5-8f52f9f6cc70'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana kondisi proyek yang sedang ditangani pembicara?', '{"audio_text": "このプロジェクトはまだ始まったばかりですが、チームの雰囲気はとてもいいです。", "options": [{"id": "opt_1", "text": "Proyeknya sudah hampir selesai minggu ini"}, {"id": "opt_2", "text": "Proyeknya baru saja dimulai, namun suasana timnya sangat baik"}, {"id": "opt_3", "text": "Proyeknya terpaksa ditunda karena kekurangan anggota"}, {"id": "opt_4", "text": "Proyeknya baru saja berganti pimpinan tim"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, 'まだ始まったばかりですが berarti ''meskipun baru saja dimulai''.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('938af993-af48-5707-8d98-bb3efa6a7bcd'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼は去年結婚した ___ なのに、もう海外へ転勤になりました。', '{"options": ["ばかり", "はず", "おかげ", "せい"], "translation": "Padahal dia baru saja menikah tahun lalu, sudah dipindahtugaskan ke luar negeri.", "sentence_template": "彼は去年結婚した [blank] なのに、もう海外へ転勤になりました。"}'::jsonb, '{"selected": "ばかり"}'::jsonb, '～たばかり bersifat subjektif: meski sudah setahun lalu, pembicara merasa kejadian itu masih sangat baru.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('046dd89b-98fc-5b1b-b30e-6be32fe321e5'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi frasa nomina: 焼きたてのパンや、入れた ___ のコーヒーが楽しめます。', '{"options": ["ばかり", "うち", "はず", "こと"], "translation": "Anda bisa menikmati roti yang baru dipanggang dan kopi yang baru diseduh.", "sentence_template": "焼きたてのパンや、入れた [blank] のコーヒーが楽しめます。"}'::jsonb, '{"selected": "ばかり"}'::jsonb, '入れたばかりのコーヒー berarti kopi yang baru saja diseduh.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('85b575f7-6cf4-56c9-9086-9861a0282308'::uuid, '74078ccb-0e75-50ad-b423-ee176374a89f'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 部屋を掃除 ___ ばかりなのに、もう散らかっています。', '{"options": ["した", "する", "して", "します"], "translation": "Padahal baru saja membersihkan kamar, sudah berantakan lagi.", "sentence_template": "部屋を掃除 [blank] ばかりなのに、もう散らかっています。"}'::jsonb, '{"selected": "した"}'::jsonb, '掃除した (Bentuk-TA) + ばかりなのに.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, '8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, 'Bicara & Rakit Kisah Awal Baru', 'Bicara Awal Baru', 'n3-u9-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('a72065b5-b4eb-59d6-bb44-8318251a6dd2'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena baru pindah, saya belum mengenal lingkungan sekitar."', '{"display_text": "引っ越したばかりなので、近所のことがわかりません。", "romaji": "Hikkoshita bakari na node, kinjo no koto ga wakarimasen.", "phonetic_breakdown": ["hik-ko-shi-ta", "ba-ka-ri na no-de", "kin-jo no ko-to ga", "wa-ka-ri-ma-sen"]}'::jsonb, '{"expected_transcript": "引っ越したばかりなので、近所のことがわかりません。"}'::jsonb, '近所 (kinjo) berarti lingkungan tetangga sekitar rumah.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('064b92e0-0461-5ecc-bfba-6b24ecc8b359'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapatnya baru saja selesai."', '{"display_text": "会議はたった今終わったばかりです。", "romaji": "Kaigi wa tatta ima owatta bakari desu.", "phonetic_breakdown": ["ka-i-gi wa", "tat-ta i-ma", "o-wat-ta", "ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript": "会議はたった今終わったばかりです。"}'::jsonb, 'たった今 (tatta ima = baru saja detik ini) memperkuat nuansa ～たばかり.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('468641f7-356d-57b5-9286-47c2d16f8649'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru mulai belajar bahasa Jepang tahun lalu."', '{"display_text": "去年日本語の勉強を始めたばかりです。", "romaji": "Kyonen nihongo no benkyou o hajimeta bakari desu.", "phonetic_breakdown": ["kyo-nen", "ni-hon-go no", "ben-kyou o", "ha-ji-me-ta", "ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript": "去年日本語の勉強を始めたばかりです。"}'::jsonb, 'Ungkapan rendah hati yang bagus saat memperkenalkan diri kepada penutur asli.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bbc2612a-d65c-54a1-9a92-cca914f8d158'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Keretanya baru saja berangkat."', '{"tokens": ["ばかりです。", "今", "出る", "出て", "電車は", "出た"], "target_translation": "Keretanya baru saja berangkat.", "romaji": "Densha wa ima deta bakari desu."}'::jsonb, '["電車は", "今", "出た", "ばかりです。"]'::jsonb, '出た (Bentuk-TA dari 出る) + ばかりです.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('93888133-0bc0-5fb6-b567-8710424286e1'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Ini adalah sepatu yang baru saja saya beli."', '{"tokens": ["これは", "靴です。", "ばかりの", "買って", "ばかりな", "買った"], "target_translation": "Ini adalah sepatu yang baru saja saya beli.", "romaji": "Kore wa katta bakari no kutsu desu."}'::jsonb, '["これは", "買った", "ばかりの", "靴です。"]'::jsonb, '買ったばかりの靴 (sepatu yang baru dibeli).', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('44064973-f8f0-56b5-bcaa-11f922a4fd55'::uuid, 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena baru bangun tidur, saya masih mengantuk."', '{"tokens": ["ばかりなので、", "起きた", "はずなので、", "まだ", "起きて", "眠いです。"], "target_translation": "Karena baru bangun tidur, saya masih mengantuk.", "romaji": "Okita bakari na node, mada nemui desu."}'::jsonb, '["起きた", "ばかりなので、", "まだ", "眠いです。"]'::jsonb, '起きたばかりなので berarti ''karena baru saja bangun''.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, '8b1590db-2b67-5793-8a24-f6c2afae1fc8'::uuid, 'Evaluasi Unit 9: Pengalaman Baru', 'Tes Unit 9', 'n3-u9-tes-akhir', 'trophy', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7b685eb7-f82e-5276-9791-173a0fe02243'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang tepat: さっき帰国 ___ ばかりなので、まだ時差ぼけがあります。', '{"options": ["した", "する", "して", "します"], "translation": "Karena baru saja pulang ke tanah air tadi, saya masih mengalami jet lag.", "sentence_template": "さっき帰国 [blank] ばかりなので、まだ時差ぼけがあります。"}'::jsonb, '{"selected": "した"}'::jsonb, '帰国した (Bentuk-TA) + ばかりなので.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7bc0afba-eec6-53c6-92af-5759fce32e64'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi frasa nomina: 先週届いた ___ の家具を組み立てています。', '{"options": ["ばかり", "はず", "うち", "せい"], "translation": "Saya sedang merakit perabot yang baru saja tiba minggu lalu.", "sentence_template": "先週届いた [blank] の家具を組み立てています。"}'::jsonb, '{"selected": "ばかり"}'::jsonb, '届いたばかりの家具 berarti perabot yang baru saja sampai.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bb3e3756-db59-5467-a557-c0b03b381568'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa langsung menerima tugas tambahan tersebut?', '{"audio_text": "新しい部署に異動したばかりで、今の業務を覚えるので精一杯なんです。", "options": [{"id": "opt_1", "text": "Karena ia akan mengambil cuti panjang minggu depan"}, {"id": "opt_2", "text": "Karena ia sedang dinas di luar kota"}, {"id": "opt_3", "text": "Karena baru pindah divisi dan masih berjuang menguasai tugas saat ini"}, {"id": "opt_4", "text": "Karena komputernya sedang dalam perbaikan"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '新しい部署に異動したばかりで berarti baru saja mutasi ke divisi baru.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('dfde6e51-f1d1-5bbf-9745-600c14cd1ca8'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'listening', 'listening_choice', 'Apa yang terjadi pada baju kemeja pembicara?', '{"audio_text": "今朝アイロンをかけたばかりのシャツに、コーヒーをこぼしてしまいました。", "options": [{"id": "opt_1", "text": "Kancing kemejanya lepas saat naik kereta"}, {"id": "opt_2", "text": "Kemejanya tertukar di tempat binatu"}, {"id": "opt_3", "text": "Ia lupa menyetrika kemejanya pagi ini"}, {"id": "opt_4", "text": "Kemeja yang baru disetrika pagi ini ketumpahan kopi"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '今朝アイロンをかけたばかりのシャツに、コーヒーをこぼしてしまいました berarti menumpahkan kopi ke kemeja yang baru disetrika.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1e47fa12-ebaf-5625-8d41-ea3691fcf184'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena baru datang ke kota ini, saya belum punya banyak teman."', '{"tokens": ["まだ友達が", "少ないです。", "ばかりなので、", "この町に", "多いです。", "来て", "来た"], "target_translation": "Karena baru datang ke kota ini, saya belum punya banyak teman.", "romaji": "Kono machi ni kita bakari na node, mada tomodachi ga sukunai desu."}'::jsonb, '["この町に", "来た", "ばかりなので、", "まだ友達が", "少ないです。"]'::jsonb, '来たばかりなので menyatakan kondisi baru tiba di kota tersebut.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('2d145534-d3ea-565c-85a5-16c3f996d3ed'::uuid, '59d92772-1879-5646-ba88-c5a41ab5c4e6'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-009' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru saja masuk perusahaan ini bulan lalu."', '{"display_text": "先月この会社に入社したばかりです。", "romaji": "Sengetsu kono kaisha ni nyuusha shita bakari desu.", "phonetic_breakdown": ["sen-ge-tsu", "ko-no ka-i-sha ni", "nyuu-sha shi-ta", "ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript": "先月この会社に入社したばかりです。"}'::jsonb, 'Kalimat perkenalan standar yang sopan bagi karyawan baru di Jepang.', 6);
    INSERT INTO units (id, level_id, title, description, unit_type, order_index) VALUES ('586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, v_level_id, 'Ragam & Penyebab (～によって)', 'Kuasai penggunaan serbaguna ～によって untuk menyatakan perbedaan budaya, cara kerja, penyebab resmi, serta persiapan penuh menuju JLPT N3.', 'curriculum', 10);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, '586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, 'Kosakata Budaya, Metode & Kesiapan N3', 'Kosakata Budaya', 'n3-u10-kosakata', 'translate', 15, 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('794a6393-f9f5-5d3e-ba82-ce344c6de3f1'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat lintas budaya: 国が変われば、食事の ___ も大きく異なります。', '{"options": ["マナー", "エラー", "カラー", "タイマー"], "translation": "Jika negaranya berbeda, tata krama/kebiasaan makannya pun sangat berbeda.", "sentence_template": "国が変われば、食事の [blank] も大きく異なります。"}'::jsonb, '{"selected": "マナー"}'::jsonb, '食事のマナー (shokuji no manaa) berarti etika atau tata krama makan.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('365a2b5c-0b8f-5e1a-adec-2a4064ad7978'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk cara kerja: 効率的な仕事の ___ を探しています。', '{"options": ["方法", "方向", "訪問", "放送"], "translation": "Saya sedang mencari metode kerja yang efisien.", "sentence_template": "効率的な仕事の [blank] を探しています。"}'::jsonb, '{"selected": "方法"}'::jsonb, '方法 (houhou) berarti metode atau cara.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('748e36b2-20c3-57f1-b28b-4537b542f15a'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat keragaman: 日本は ___ によって方言や料理が違います。', '{"options": ["地域", "地球", "地下", "地図"], "translation": "Di Jepang, dialek dan masakannya berbeda tergantung wilayahnya.", "sentence_template": "日本は [blank] によって方言や料理が違います。"}'::jsonb, '{"selected": "地域"}'::jsonb, '地域 (chiiki) berarti wilayah atau daerah.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4808ab0c-1f24-592c-ad90-c0c59d20c64d'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata untuk ujian N3: 試験の ___ に合わせて、本番と同じ時間で練習します。', '{"options": ["形式", "景色", "知識", "意識"], "translation": "Menyesuaikan dengan format ujian, saya berlatih dengan durasi sama seperti ujian asli.", "sentence_template": "試験の [blank] に合わせて、本番と同じ時間で練習します。"}'::jsonb, '{"selected": "形式"}'::jsonb, '試験の形式 (shiken no keishiki) berarti format/pola soal ujian.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('4b36bebf-2c0a-561f-bcce-de176bb82b4a'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'listening', 'listening_choice', 'Apa yang berbeda tergantung musim menurut pembicara?', '{"audio_text": "この旅館では、季節ごとに旬の食材を使った特別な料理が用意されています。", "options": [{"id": "opt_1", "text": "Hidangan khusus memakai bahan musiman yang disediakan penginapan"}, {"id": "opt_2", "text": "Harga tiket kereta menuju penginapan tersebut"}, {"id": "opt_3", "text": "Jam buka pemandian air panas di lantai dua"}, {"id": "opt_4", "text": "Jumlah kamar yang boleh dipesan oleh wisatawan asing"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '季節ごとに旬の食材を使った特別な料理 berarti hidangan khusus berbahan musiman tiap musim.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('53e5710c-223f-504a-8efe-4655f236c0e1'::uuid, '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana cara belajar yang paling efektif menurut pembicara?', '{"audio_text": "人それぞれ生活リズムが違うので、自分に合った勉強法を見つけることが一番大切です。", "options": [{"id": "opt_1", "text": "Belajar tepat tiga jam setiap malam tanpa jeda"}, {"id": "opt_2", "text": "Menemukan metode belajar yang sesuai dengan ritme hidup sendiri"}, {"id": "opt_3", "text": "Menghafal seluruh kamus dari halaman pertama"}, {"id": "opt_4", "text": "Hanya belajar bersama kelompok besar setiap akhir pekan"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, '自分に合った勉強法を見つけることが一番大切です berarti menemukan cara belajar yang cocok untuk diri sendiri adalah yang terpenting.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, '586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, 'Pola ～によって & ～による', 'Pola Ni Yotte', 'n3-u10-pola-utama', 'book-open', 20, 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('95378fa8-00f8-52b0-b8d7-c85c46a0c216'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat keragaman: 国 ___ 挨拶の仕方が違います。', '{"options": ["によって", "に対して", "にとって", "について"], "translation": "Tergantung negaranya, cara menyapanya berbeda.", "sentence_template": "国 [blank] 挨拶の仕方が違います。"}'::jsonb, '{"selected": "によって"}'::jsonb, 'Nomina + によって menyatakan variasi atau perbedaan yang bergantung pada suatu faktor.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8ece1aeb-25da-5903-a058-913219536a51'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'reading', 'fill_blank', 'Pilih bentuk yang menerangkan nomina: 大雨 ___ 被害が広がっています。', '{"options": ["による", "によって", "によった", "によります"], "translation": "Kerusakan akibat hujan deras terus meluas.", "sentence_template": "大雨 [blank] 被害が広がっています。"}'::jsonb, '{"selected": "による"}'::jsonb, 'Ketika menerangkan kata benda (被害 = kerusakan), によって berubah menjadi による.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('b2c3c1f5-7270-560d-9e53-ef8d90f05a48'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'reading', 'fill_blank', 'Lengkapi kalimat cara/metode: インターネットの普及 ___ 、働き方が変わりました。', '{"options": ["によって", "に対して", "のおかげで", "のうちに"], "translation": "Melalui/karena meluasnya internet, cara bekerja telah berubah.", "sentence_template": "インターネットの普及 [blank] 、働き方が変わりました。"}'::jsonb, '{"selected": "によって"}'::jsonb, 'Nomina + によって menyatakan sebab objektif atau sarana terjadinya perubahan.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('98f34f44-6668-5806-b796-0ce04e130d3d'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung orangnya, pendapatnya berbeda."', '{"tokens": ["対して", "意見が", "よる", "違います。", "よって", "人に"], "target_translation": "Tergantung orangnya, pendapatnya berbeda.", "romaji": "Hito ni yotte iken ga chigaimasu."}'::jsonb, '["人に", "よって", "意見が", "違います。"]'::jsonb, '人によって berarti ''tergantung orangnya''.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('aab60955-99a4-5d94-80dc-5c3ff6c1fdef'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Gedung ini dirancang oleh arsitek terkenal."', '{"tokens": ["よる", "設計されました。", "有名な建築家に", "設計しました。", "この建物は", "よって"], "target_translation": "Gedung ini dirancang oleh arsitek terkenal.", "romaji": "Kono tatemono wa yuumeina kenchikuka ni yotte sekkei saremashita."}'::jsonb, '["この建物は", "有名な建築家に", "よって", "設計されました。"]'::jsonb, 'Dalam kalimat pasif karya/bangunan, pelaku ditandai dengan によって.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('c9e71cca-1d93-52b8-a106-44a1f870104e'::uuid, '91662d89-eef5-5734-b1fa-90f73f5178b9'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'listening', 'listening_choice', 'Apa yang memengaruhi tarif kamar hotel tersebut?', '{"audio_text": "このホテルの宿泊料金は、季節や曜日によって大きく変わります。", "options": [{"id": "opt_1", "text": "Jumlah barang bawaan yang dibawa tamu"}, {"id": "opt_2", "text": "Metode pembayaran tunai atau kartu kredit"}, {"id": "opt_3", "text": "Musim dan hari dalam seminggu"}, {"id": "opt_4", "text": "Lama waktu tamu menginap di hotel sebelumnya"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '季節や曜日によって大きく変わります berarti berubah besar tergantung musim dan hari.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, '586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, 'Simak & Baca: Perbedaan & Fakta Resmi', 'Simak Fakta', 'n3-u10-dengar-baca', 'graduation-cap', 20, 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e7a0735c-8ef3-5280-bcde-0c694df6207c'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'listening', 'listening_choice', 'Bagaimana cara menentukan pemenang lomba desain tersebut?', '{"audio_text": "最優秀作品は、審査員の評価と一般の方々による投票で決定されます。", "options": [{"id": "opt_1", "text": "Ditentukan sepenuhnya melalui undian acak"}, {"id": "opt_2", "text": "Dipilih hanya oleh ketua panitia lomba"}, {"id": "opt_3", "text": "Ditentukan berdasarkan kecepatan waktu pengumpulan"}, {"id": "opt_4", "text": "Ditentukan oleh penilaian juri dan pemungutan suara masyarakat umum"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '審査員の評価と一般の方々による投票 berarti penilaian juri dan voting oleh masyarakat umum.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('55502efc-0fed-5593-b158-29460c7bc811'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'listening', 'listening_choice', 'Mengapa aturan pembuangan sampah perlu dicek setiap kali pindah kota?', '{"audio_text": "日本では自治体によってゴミの分別ルールが異なるため、引っ越したら必ず確認が必要です。", "options": [{"id": "opt_1", "text": "Karena aturan pemilahan sampah berbeda tergantung pemerintah daerah"}, {"id": "opt_2", "text": "Karena jadwal truk sampah berubah setiap minggu"}, {"id": "opt_3", "text": "Karena kantong sampah hanya dijual di balai kota"}, {"id": "opt_4", "text": "Karena warga baru mendapat pengecualian selama sebulan"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '自治体によってゴミの分別ルールが異なる berarti aturan pemilahan sampah berbeda tergantung pemerintah kota/daerah.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('e35720d1-f97f-585e-b300-936d23cc2ac2'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'listening', 'listening_choice', 'Apa dampak positif dari penerapan sistem kerja baru menurut audio?', '{"audio_text": "テレワークの導入によって、社員の通勤時間が減り、生産性が向上しました。", "options": [{"id": "opt_1", "text": "Perusahaan berhasil mengurangi jumlah rapat mingguan menjadi nol"}, {"id": "opt_2", "text": "Waktu perjalanan pegawai berkurang dan produktivitas meningkat"}, {"id": "opt_3", "text": "Seluruh kantor cabang di luar Tokyo ditutup permanen"}, {"id": "opt_4", "text": "Biaya listrik kantor meningkat dua kali lipat"}]}'::jsonb, '{"selected_id": "opt_2"}'::jsonb, 'テレワークの導入によって...通勤時間が減り、生産性が向上しました.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('8707bebc-b37a-5415-afb6-bfba31252f3e'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 状況 ___ 、柔軟に対応することが求められます。', '{"options": ["によって", "による", "に対して", "にとって"], "translation": "Tergantung situasinya, kita dituntut merespons secara fleksibel.", "sentence_template": "状況 [blank] 、柔軟に対応することが求められます。"}'::jsonb, '{"selected": "によって"}'::jsonb, '状況によって berarti tergantung pada situasi/keadaan.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('36181fdc-f4b5-5256-96f0-2534be8077e9'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi frasa berita resmi: 地震 ___ 交通機関の乱れはすべて解消しました。', '{"options": ["による", "によって", "に対する", "における"], "translation": "Gangguan transportasi akibat gempa bumi telah teratasi seluruhnya.", "sentence_template": "地震 [blank] 交通機関の乱れはすべて解消しました。"}'::jsonb, '{"selected": "による"}'::jsonb, '交通機関の乱れ (gangguan transportasi) adalah nomina, sehingga memakai による.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('bf238178-0b6a-5862-b1b5-17a19fa93124'::uuid, 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf'::uuid, NULL, 'reading', 'fill_blank', 'Pilih ungkapan variasi: 場合 ___ 、オンライン面談に変更することも可能です。', '{"options": ["によっては", "によるは", "に対しては", "にとっては"], "translation": "Tergantung keadaannya, memungkinkan juga diubah menjadi pertemuan daring.", "sentence_template": "場合 [blank] 、オンライン面談に変更することも可能です。"}'::jsonb, '{"selected": "によっては"}'::jsonb, '場合によっては berarti ''tergantung kasusnya / dalam kondisi tertentu''.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('202f4a77-338c-5986-b953-bd733c212f61'::uuid, '586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, 'Bicara & Rakit Analisis N3', 'Bicara Analisis', 'n3-u10-bicara-rakit', 'microphone', 20, 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('978a5dfa-3a46-5996-b468-4b0e00949ad2'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Cara berpikir berbeda tergantung orangnya."', '{"display_text": "人によって考え方が違います。", "romaji": "Hito ni yotte kangaekata ga chigaimasu.", "phonetic_breakdown": ["hi-to ni", "yot-te", "kan-ga-e-ka-ta ga", "chi-ga-i-ma-su"]}'::jsonb, '{"expected_transcript": "人によって考え方が違います。"}'::jsonb, 'Kalimat inti N3 yang sangat sering dipakai dalam diskusi lintas budaya.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('1a98607f-778b-5130-a238-d37225adedae'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat diskusi, masalahnya berhasil diselesaikan."', '{"display_text": "話し合いによって問題が解決しました。", "romaji": "Hanashiai ni yotte mondai ga kaiketsu shimashita.", "phonetic_breakdown": ["ha-na-shi-a-i ni", "yot-te", "mon-da-i ga", "ka-i-ke-tsu", "shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "話し合いによって問題が解決しました。"}'::jsonb, '話し合いによって menunjukkan cara/sarana penyelesaian masalah secara formal.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('d96493cb-aa94-5cf5-8229-4c901368eb63'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tergantung keadaannya, jadwal bisa saja berubah."', '{"display_text": "場合によっては予定が変わることもあります。", "romaji": "Baai ni yotte wa yotei ga kawaru koto mo arimasu.", "phonetic_breakdown": ["ba-a-i ni", "yot-te wa", "yo-te-i ga", "ka-wa-ru", "ko-to mo", "a-ri-ma-su"]}'::jsonb, '{"expected_transcript": "場合によっては予定が変わることもあります。"}'::jsonb, '場合によっては + ～こともあります adalah kombinasi alami untuk menjelaskan kemungkinan fleksibel.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('ea13b5e9-1a42-5971-b98e-916427c41c6f'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung musimnya, pemandangan di sini berubah."', '{"tokens": ["対して", "よる", "季節に", "変わります。", "よって", "ここの景色が"], "target_translation": "Tergantung musimnya, pemandangan di sini berubah.", "romaji": "Kisetsu ni yotte koko no keshiki ga kawarimasu."}'::jsonb, '["季節に", "よって", "ここの景色が", "変わります。"]'::jsonb, '季節によって + 変わります menyatakan variasi berdasarkan musim.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('678d2b71-4f2f-58ec-863b-fd506d894773'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Ada jadwal pengiriman akibat badai salju yang tertunda."', '{"tokens": ["よって", "対する", "配送の遅れが", "あります。", "よる", "大雪に"], "target_translation": "Pengiriman tertunda akibat badai salju.", "romaji": "Ooyuki ni yoru haisou no okure ga arimasu."}'::jsonb, '["大雪に", "よる", "配送の遅れが", "あります。"]'::jsonb, '配送の遅れ adalah nomina sehingga menggunakan による.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0ea711b3-a9e8-5c1e-a832-036fd964a15d'::uuid, '202f4a77-338c-5986-b953-bd733c212f61'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Saya belajar bahasa Jepang melalui pertukaran budaya."', '{"tokens": ["せいで", "よって", "日本語を", "学びました。", "よる", "文化交流に"], "target_translation": "Saya belajar bahasa Jepang melalui pertukaran budaya.", "romaji": "Bunka kouryuu ni yotte nihongo o manabimashita."}'::jsonb, '["文化交流に", "よって", "日本語を", "学びました。"]'::jsonb, '文化交流によって menyatakan sarana/metode pembelajaran.', 6);
    INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index) VALUES ('a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, '586d7103-1d5f-5c15-9dcc-69e13624da71'::uuid, 'Ujian Kesiapan JLPT N3 (Review Terpadu)', 'Tes Kesiapan N3', 'n3-u10-tes-akhir', 'target', 25, 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('54c6df2c-57a8-5221-9754-204d67125c2a'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'reading', 'fill_blank', 'Pilih pola yang tepat untuk konteks budaya: 文化の違い ___ 、同じ言葉でも受け取り方が変わります。', '{"options": ["によって", "による", "に対して", "のおかげで"], "translation": "Tergantung perbedaan budaya, cara menangkap kata yang sama pun bisa berubah.", "sentence_template": "文化の違い [blank] 、同じ言葉でも受け取り方が変わります。"}'::jsonb, '{"selected": "によって"}'::jsonb, '文化の違いによって berarti bergantung pada perbedaan budaya.', 1);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('fa72b794-f6a9-57ef-9993-9a4bf6a3a82a'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'reading', 'fill_blank', 'Uji ketelitian bentuk modifikasi nomina: 専門家 ___ 詳しい解説を聞きました。', '{"options": ["による", "によって", "に対する", "における"], "translation": "Saya mendengarkan penjelasan rinci oleh seorang ahli.", "sentence_template": "専門家 [blank] 詳しい解説を聞きました。"}'::jsonb, '{"selected": "による"}'::jsonb, '詳しい解説 adalah frasa nomina sehingga memakai による.', 2);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('85e7d1b2-119b-5ed9-9230-c001c1569d6e'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'listening', 'listening_choice', 'Pesan utama apa yang disampaikan pembicara kepada peserta menjelang ujian N3?', '{"audio_text": "毎日の積み重ねによって実力は確実につきますから、本番まで自信を持って頑張ってください。", "options": [{"id": "opt_1", "text": "Peserta sebaiknya berhenti belajar dua minggu sebelum ujian"}, {"id": "opt_2", "text": "Soal ujian tahun ini jauh lebih sulit daripada tahun lalu"}, {"id": "opt_3", "text": "Kemampuan pasti terbentuk lewat latihan rutin harian, jadi tetap percaya diri"}, {"id": "opt_4", "text": "Hasil ujian hanya bergantung pada hafalan kanji semata"}]}'::jsonb, '{"selected_id": "opt_3"}'::jsonb, '毎日の積み重ねによって実力は確実につきます berarti kemampuan pasti terbangun melalui akumulasi usaha setiap hari.', 3);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('7b3cc3a3-2480-5121-b7e6-3bc589bb883d'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'listening', 'listening_choice', 'Apa yang berubah pada jadwal kereta menurut pengumuman resmi ini?', '{"audio_text": "強風による安全確認のため、一部区間で運転を見合わせています。", "options": [{"id": "opt_1", "text": "Kereta ekspres diganti menjadi kereta lokal gratis"}, {"id": "opt_2", "text": "Pintu masuk selatan stasiun ditutup sementara"}, {"id": "opt_3", "text": "Tiket kereta jarak jauh mengalami penyesuaian harga"}, {"id": "opt_4", "text": "Operasi kereta di sebagian jalur dihentikan sementara untuk pemeriksaan keselamatan akibat angin kencang"}]}'::jsonb, '{"selected_id": "opt_4"}'::jsonb, '強風による安全確認のため、一部区間で運転を見合わせています adalah pengumuman resmi khas kereta Jepang.', 4);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('64630df8-0e30-574e-8cf6-cf2143120325'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung perusahaan, aturan pakaian kerjanya berbeda."', '{"tokens": ["対して", "よる", "会社に", "よって", "服装のルールが", "違います。"], "target_translation": "Tergantung perusahaan, aturan pakaian kerjanya berbeda.", "romaji": "Kaisha ni yotte fukusou no ruuru ga chigaimasu."}'::jsonb, '["会社に", "よって", "服装のルールが", "違います。"]'::jsonb, '会社によって + 違います menunjukkan perbedaan aturan antarperusahaan.', 5);
    INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index) VALUES ('0cc0381c-4e3f-5742-9106-15d8fb308a62'::uuid, 'a367fad4-a7fd-51eb-a82f-007525796e71'::uuid, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N3-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat usaha terus-menerus, saya siap menghadapi JLPT N3."', '{"display_text": "日々の努力によって、N3の試験に臨む準備ができました。", "romaji": "Hibi no doryoku ni yotte, enu san no shiken ni nozomu junbi ga dekimashita.", "phonetic_breakdown": ["hi-bi no", "do-ryo-ku ni", "yot-te", "e-nu san no", "shi-ken ni no-zo-mu", "jun-bi ga", "de-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript": "日々の努力によって、N3の試験に臨む準備ができました。"}'::jsonb, '臨む (nozomu) berarti menghadapi (ujian/tantangan). Kalimat penutup yang mantap untuk menyelesaikan seluruh kurikulum N3!', 6);
